def session_of(ny_hour: float) -> str:
    h = int(ny_hour)
    if h >= 17 or h < 1:
        return "asia"
    if h < 5:
        return "london"
    if h < 7:
        return "preny"
    if h < 10:
        return "ny"
    if h < 12:
        return "lclose"
    return "nypm"


def _clean(v) -> float:
    if v is None:
        return 0.0
    try:
        v = float(v)
    except (TypeError, ValueError):
        return 0.0
    return 0.0 if (math.isnan(v) or math.isinf(v)) else v


def _transform(feats: Dict[str, float], numeric: List[str], log: bool = True) -> Dict[str, float]:
    """Feature engineering shared by training and inference."""
    out: Dict[str, float] = {}
    for k in numeric:
        v = _clean(feats.get(k, 0.0))
        if log and k in LOG_FEATURES:
            v = math.log1p(max(v, 0.0))
        out[k] = v
    s = session_of(_clean(feats.get("ny_hour", 12)) or 12)
    for name in SESSIONS:
        out[f"sess_{name}"] = 1.0 if s == name else 0.0
    out["ny_hour_raw"] = _clean(feats.get("ny_hour", 12))
    return out


KIND_DUMMIES = [f"kind_{k}" for k in KINDS]
FEATURE_ORDER = NUMERIC + [f"sess_{s}" for s in SESSIONS] + ["ny_hour_raw"] + KIND_DUMMIES
FEATURE_ORDER_V5 = NUMERIC_V5 + [f"sess_{s}" for s in SESSIONS] + ["ny_hour_raw"] + KIND_DUMMIES
FEATURE_ORDER_V4 = NUMERIC_V4 + [f"sess_{s}" for s in SESSIONS] + ["ny_hour_raw"] + KIND_DUMMIES
FEATURE_ORDER_V3 = NUMERIC_V3 + [f"sess_{s}" for s in SESSIONS] + ["ny_hour_raw"] + KIND_DUMMIES
FEATURE_ORDER_V2 = NUMERIC_V2 + [f"sess_{s}" for s in SESSIONS] + ["ny_hour_raw"] + KIND_DUMMIES
FEATURE_ORDER_V1 = NUMERIC_V1 + [f"sess_{s}" for s in SESSIONS]


# ------------------------------------------------------------- tree model
def _compile_trees(trees: List[Dict]) -> List[Tuple[np.ndarray, ...]]:
    """JSON lists -> numpy arrays once (feat, thr, left, right, leaf, val) per tree."""
    return [(np.asarray(t["f"], dtype=int), np.asarray(t["t"], dtype=float), np.asarray(t["l"], dtype=int),
             np.asarray(t["r"], dtype=int), np.asarray(t["leaf"], dtype=bool), np.asarray(t["v"], dtype=float))
            for t in trees]


def _compile_trees_py(trees: List[Dict]) -> List[Tuple[list, ...]]:
    """Plain Python lists per tree (feat, thr, left, right, leaf, val) for the scalar fast path."""
    return [(list(map(int, t["f"])), list(map(float, t["t"])), list(map(int, t["l"])), list(map(int, t["r"])),
             list(map(bool, t["leaf"])), list(map(float, t["v"]))) for t in trees]


def _predict_one(ptrees, x: np.ndarray, baseline: float) -> float:
    """Scalar raw score for one sample (plain Python loops over pre-converted lists are
    ~20x faster than numpy indexing for a single row)."""
    xl = x.tolist()
    out = baseline
    for f, t, l, r, lf, val in ptrees:
        node = 0
        while not lf[node]:
            node = l[node] if xl[f[node]] <= t[node] else r[node]
        out += val[node]
    return out


def _predict_trees(trees: List[Dict], X: np.ndarray, baseline: float, ctrees=None) -> np.ndarray:
    """Vectorised raw-score prediction for exported HistGradientBoosting trees."""
    out = np.full(len(X), baseline, dtype=float)
    rows = np.arange(len(X))
    for feat, thr, left, right, leaf, val in (ctrees or _compile_trees(trees)):
        idx = np.zeros(len(X), dtype=int)
        for _ in range(64):
            is_leaf = leaf[idx]
            if is_leaf.all():
                break
            go_left = X[rows, feat[idx]] <= thr[idx]
            nxt = np.where(go_left, left[idx], right[idx])
            idx = np.where(is_leaf, idx, nxt)
        out += val[idx]
    return out


def _explain_trees(trees: List[Dict], x: np.ndarray, n_features: int, ctrees=None) -> np.ndarray:
    """Saabas path contributions for one sample: change of node value along the path
    is attributed to the feature that was split on."""
    contrib = np.zeros(n_features, dtype=float)
    for feat, thr, left, right, leaf, val in (ctrees or _compile_trees(trees)):
        node = 0
        for _ in range(64):
            if leaf[node]:
                break
            nxt = left[node] if x[feat[node]] <= thr[node] else right[node]
            contrib[feat[node]] += val[nxt] - val[node]
            node = nxt
    return contrib


def _export_hgb(clf) -> Dict:
    """Export a fitted HistGradientBoostingClassifier into JSON-serialisable trees."""
    trees = []
    for it in clf._predictors:
        nodes = it[0].nodes
        trees.append({
            "f": nodes["feature_idx"].astype(int).tolist(),
            "t": nodes["num_threshold"].astype(float).tolist(),
            "l": nodes["left"].astype(int).tolist(),
            "r": nodes["right"].astype(int).tolist(),
            "leaf": nodes["is_leaf"].astype(bool).tolist(),
            "v": nodes["value"].astype(float).tolist(),
        })
    # internal node values are 0 in sklearn's arrays; fill them with the
    # count-weighted mean of their children so Saabas explanations are meaningful
    for t, it in zip(trees, clf._predictors):
        nodes = it[0].nodes
        v = np.array(t["v"], dtype=float)
        cnt = nodes["count"].astype(float)
        for n in range(len(v) - 1, -1, -1):
            if not t["leaf"][n]:
                l, r = t["l"][n], t["r"][n]
                tot = cnt[l] + cnt[r]
                v[n] = (v[l] * cnt[l] + v[r] * cnt[r]) / tot if tot > 0 else 0.5 * (v[l] + v[r])
        t["v"] = v.tolist()
    return {"kind": "gbm", "trees": trees, "baseline": float(np.ravel(clf._baseline_prediction)[0])}


# ------------------------------------------------------------------ scorer
@dataclass
class QualityScorer:
    """kind -> model dict.  Model dicts are either
       {"kind": "logistic", "w", "b", "mu", "sd", "n", "rate"}   (v1)
    or {"kind": "gbm", "trees", "baseline", "n", "rate"}          (v2)
    """
    models: Dict[str, Dict] = field(default_factory=dict)
    base_rate: Dict[str, float] = field(default_factory=dict)
    features: List[str] = field(default_factory=lambda: list(FEATURE_ORDER))
    meta: Dict = field(default_factory=dict)
    _compiled: Dict[str, list] = field(default_factory=dict, repr=False)
    _compiled_py: Dict[str, list] = field(default_factory=dict, repr=False)

    def _ctrees(self, kind_key: str, m: Dict) -> list:
        c = self._compiled.get(kind_key)
        if c is None:
            c = self._compiled[kind_key] = _compile_trees(m["trees"])
        return c

    def _ptrees(self, kind_key: str, m: Dict) -> list:
        c = self._compiled_py.get(kind_key)
        if c is None:
            c = self._compiled_py[kind_key] = _compile_trees_py(m["trees"])
        return c

    # ----------------------------------------------------------- vectors
    @property
    def numeric(self) -> List[str]:
        return [f for f in self.features if not f.startswith("sess_") and not f.startswith("kind_") and f != "ny_hour_raw"]

    def vector(self, feats: Dict[str, float], kind: Optional[str] = None) -> np.ndarray:
        t = _transform(feats, self.numeric)
        if kind is not None:
            for k in KINDS:
                t[f"kind_{k}"] = 1.0 if kind == k else 0.0
        return np.array([t.get(k, 0.0) for k in self.features], dtype=float)

    def matrix(self, rows, kinds: Optional[List[str]] = None) -> np.ndarray:
        """rows: list of raw feature dicts, an already-built matrix (returned as is) or a
        pandas DataFrame whose columns are the raw feature names (vectorised transform)."""
        if isinstance(rows, np.ndarray):
            return rows
        if hasattr(rows, "columns"):
            return self.matrix_from_frame(rows, kinds)
        if not len(rows):
            return np.zeros((0, len(self.features)))
        kinds = kinds or [None] * len(rows)
        return np.vstack([self.vector(r, k) for r, k in zip(rows, kinds)])

    def matrix_from_frame(self, df, kinds: Optional[List[str]] = None) -> np.ndarray:
        """Vectorised equivalent of ``vector`` for a frame of raw feature columns
        (missing columns -> 0, NaN -> 0, log1p on LOG_FEATURES, session dummies, kind dummies)."""
        n = len(df)
        X = np.zeros((n, len(self.features)), dtype=np.float64)
        ny = np.nan_to_num(df["ny_hour"].to_numpy(dtype=float), nan=12.0) if "ny_hour" in df.columns else np.full(n, 12.0)
        ny_s = np.where(ny == 0, 12.0, ny)
        sess = np.array([session_of(h) for h in ny_s])
        kinds_arr = np.array(kinds) if kinds is not None else None
        for j, name in enumerate(self.features):
            if name.startswith("sess_"):
                X[:, j] = (sess == name[5:]).astype(float)
            elif name == "ny_hour_raw":
                X[:, j] = ny
            elif name.startswith("kind_"):
                if kinds_arr is not None:
                    X[:, j] = (kinds_arr == name[5:]).astype(float)
            elif name in df.columns:
                v = np.nan_to_num(df[name].to_numpy(dtype=float), nan=0.0, posinf=0.0, neginf=0.0)
                X[:, j] = np.log1p(np.maximum(v, 0.0)) if name in LOG_FEATURES else v
        return X

    # ----------------------------------------------------------- scoring
    def _model_key(self, kind: str) -> Optional[str]:
        if kind in self.models:
            return kind
        return "ALL" if "ALL" in self.models else None

    def _model(self, kind: str) -> Optional[Dict]:
        k = self._model_key(kind)
        return None if k is None else self.models[k]

    def _raw(self, m: Dict, X: np.ndarray, key: Optional[str] = None) -> np.ndarray:
        if m.get("kind", "logistic") == "gbm":
            return _predict_trees(m["trees"], X, m["baseline"], self._ctrees(key, m) if key else None)
        Xs = np.clip((X - np.array(m["mu"])) / np.array(m["sd"]), -3.0, 3.0)
        return Xs @ np.array(m["w"]) + m["b"]

    # v6: a model file may carry a second pooled member "ALL2" (different learner on the same
    # features); probabilities of "ALL" and "ALL2" are mixed with meta["mix"] (default 50/50)
    def _mix(self) -> Optional[float]:
        if "ALL2" not in self.models:
            return None
        mix = self.meta.get("mix") if isinstance(self.meta, dict) else None
        return float(mix[0]) if mix else 0.5

    def _prob_one(self, key: str, x: np.ndarray) -> float:
        m = self.models[key]
        if m.get("kind", "logistic") == "gbm":
            z = _predict_one(self._ptrees(key, m), x, m["baseline"])
        else:
            z = float(self._raw(m, x[None, :])[0])
        return 1.0 / (1.0 + math.exp(-max(min(z, 30), -30)))

    def score(self, kind: str, feats: Dict[str, float]) -> float:
        key = self._model_key(kind)
        if key is None:
            return self.base_rate.get(kind, 0.4)
        x = self.vector(feats, kind)
        p = self._prob_one(key, x)
        mix = self._mix()
        if mix is not None and key == "ALL":
            p = mix * p + (1.0 - mix) * self._prob_one("ALL2", x)
        return p

    def score_many(self, kinds: List[str], rows) -> np.ndarray:
        """Vectorised scoring (used in training / evaluation); rows = dicts, frame or matrix."""
        X = self.matrix(rows, kinds)
        out = np.zeros(len(rows), dtype=float)
        kinds_arr = np.array(kinds)
        for k in set(kinds):
            mask = kinds_arr == k
            key = self._model_key(k)
            if key is None:
                out[mask] = self.base_rate.get(k, 0.4)
                continue
            z = np.clip(self._raw(self.models[key], X[mask], key), -30, 30)
            p = 1.0 / (1.0 + np.exp(-z))
            mix = self._mix()
            if mix is not None and key == "ALL":
                z2 = np.clip(self._raw(self.models["ALL2"], X[mask], "ALL2"), -30, 30)
                p = mix * p + (1.0 - mix) / (1.0 + np.exp(-z2))
            out[mask] = p
        return out

    def explain(self, kind: str, feats: Dict[str, float], top: int = 5) -> List[Tuple[str, float]]:
        m = self._model(kind)
        if m is None:
            return []
        x = self.vector(feats, kind)
        if m.get("kind", "logistic") == "gbm":
            contrib = _explain_trees(m["trees"], x, len(self.features), self._ctrees(self._model_key(kind), m))
            mix = self._mix()
            if mix is not None and self._model_key(kind) == "ALL":
                m2 = self.models["ALL2"]
                contrib = mix * contrib + (1.0 - mix) * _explain_trees(m2["trees"], x, len(self.features), self._ctrees("ALL2", m2))
        else:
            xs = np.clip((x - np.array(m["mu"])) / np.array(m["sd"]), -3.0, 3.0)
            contrib = xs * np.array(m["w"])
        idx = np.argsort(-np.abs(contrib))[:top]
        return [(self.features[j], round(float(contrib[j]), 3)) for j in idx if abs(contrib[j]) > 1e-9]

    @property
    def model_kind(self) -> str:
        m = self.models.get("ALL") or next(iter(self.models.values()), {})
        return m.get("kind", "logistic")

    # ------------------------------------------------------------- persistence
    def save(self, path: str | Path) -> None:
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(json.dumps({"version": 2, "models": self.models, "base_rate": self.base_rate,
                                          "features": self.features, "meta": self.meta}, indent=None))

    @classmethod
    def load(cls, path: str | Path) -> Optional["QualityScorer"]:
        if isinstance(path, str) and "+" in path:
            members, weights = [], []
            for part in path.split("+"):
                fp, _, w = part.partition("*")
                m = cls.load(fp.strip())
                if m is None:
                    return None
                members.append(m)
                weights.append(float(w) if w else 1.0)
            return EnsembleScorer(members, weights)  # type: ignore[return-value]
        p = Path(path)
        if not p.exists():
            alt = Path(__file__).resolve().parent / path  # single-file build: models/ lives next to this script
            if alt.exists():
                p = alt
            else:
                return None
        d = json.loads(p.read_text())
        models = d["models"]
        for m in models.values():
            m.setdefault("kind", "logistic")
        feats = d.get("features")
        if not feats:
            # legacy file without a feature list: infer from the weight vector length
            any_m = next(iter(models.values()), {})
            n_w = len(any_m.get("w", []))
            feats = {len(FEATURE_ORDER): FEATURE_ORDER, len(FEATURE_ORDER_V5): FEATURE_ORDER_V5, len(FEATURE_ORDER_V4): FEATURE_ORDER_V4,
                     len(FEATURE_ORDER_V3): FEATURE_ORDER_V3,
                     len(FEATURE_ORDER_V2): FEATURE_ORDER_V2}.get(n_w, FEATURE_ORDER_V1)
            feats = list(feats)
        return cls(models=models, base_rate=d.get("base_rate", {}), features=feats, meta=d.get("meta", {}))


# --------------------------------------------------------------- ensemble
@dataclass
class EnsembleScorer:
    """Average of several ``QualityScorer`` probabilities (v5: v4 structure/PA model +
    v5 indicator model).  Each member uses its own feature list, so members trained on
    different feature sets can be mixed.  Same public API as QualityScorer.

    Load with ``QualityScorer.load("models/a.json+models/b.json")`` (paths joined by '+',
    optional weights ``models/a.json*0.4+models/b.json*0.6``)."""
    members: List[QualityScorer] = field(default_factory=list)
    weights: List[float] = field(default_factory=list)

    def __post_init__(self):
        if not self.weights:
            self.weights = [1.0 / len(self.members)] * len(self.members)
        tot = sum(self.weights)
        self.weights = [w / tot for w in self.weights]

    @property
    def features(self) -> List[str]:
        return self.members[-1].features

    @property
    def meta(self) -> Dict:
        return {"ensemble": [m.meta for m in self.members], "weights": self.weights}

    @property
    def base_rate(self) -> Dict[str, float]:
        return self.members[-1].base_rate

    @property
    def model_kind(self) -> str:
        return "ensemble"

    def score(self, kind: str, feats: Dict[str, float]) -> float:
        return float(sum(w * m.score(kind, feats) for m, w in zip(self.members, self.weights)))

    def score_many(self, kinds: List[str], rows) -> np.ndarray:
        return sum(w * m.score_many(kinds, rows) for m, w in zip(self.members, self.weights))

    def explain(self, kind: str, feats: Dict[str, float], top: int = 5) -> List[Tuple[str, float]]:
        agg: Dict[str, float] = {}
        for m, w in zip(self.members, self.weights):
            for name, v in m.explain(kind, feats, top=top * 3):
                agg[name] = agg.get(name, 0.0) + w * v
        items = sorted(agg.items(), key=lambda t: -abs(t[1]))[:top]
        return [(k, round(v, 3)) for k, v in items]


# ---------------------------------------------------------------- training
#: default GBM settings - deliberately shallow / heavily regularised.  On the
#: 2025-01..2026-09 XAUUSD set this generalised best (val & test AUC ~0.63-0.64
#: with train AUC ~0.70); deeper trees fit the training period to 0.9 and lost
#: 2-3 AUC points out of sample.  See experiments_gbm.py.
GBM_DEFAULT = {"max_iter": 200, "learning_rate": 0.03, "max_depth": 3, "max_leaf_nodes": 8,
               "min_samples_leaf": 200, "l2_regularization": 5.0, "early_stopping": False, "random_state": 7}


def train(rows, y: np.ndarray, kinds: List[str], C: float = 0.3, min_rows: int = 150,
          model: str = "gbm", gbm_params: Optional[Dict] = None, per_kind: bool = False,
          sample_weight: Optional[np.ndarray] = None, scorer: Optional[QualityScorer] = None) -> QualityScorer:
    """rows: raw feature dicts (POI.features + selection context), y: 0/1 target.

    model="gbm": HistGradientBoostingClassifier (exported to JSON trees), pooled over
                 POI types with type dummies (per_kind=False, default) or one model per type.
    model="logistic": v1 standardised logistic regression.
    scorer: optional pre-built scorer (e.g. with a restricted feature list) to fit into.
    """
    scorer = scorer if scorer is not None else QualityScorer()
    X = scorer.matrix(rows, kinds)
    y = np.asarray(y).astype(int)
    kinds_arr = np.array(kinds)
    sw = None if sample_weight is None else np.asarray(sample_weight, dtype=float)

    params = dict(GBM_DEFAULT)
    if gbm_params:
        params.update(gbm_params)

    def fit(mask) -> Dict:
        Xm, ym = X[mask], y[mask]
        if model == "gbm":
            from sklearn.ensemble import HistGradientBoostingClassifier
            clf = HistGradientBoostingClassifier(**params)
            clf.fit(Xm, ym, sample_weight=None if sw is None else sw[mask])
            d = _export_hgb(clf)
            d.update({"n": int(mask.sum()), "rate": float(ym.mean()), "n_trees": len(d["trees"])})
            return d
        from sklearn.linear_model import LogisticRegression
        mu, sd = Xm.mean(0), Xm.std(0)
        sd[sd == 0] = 1.0
        clf = LogisticRegression(C=C, max_iter=5000)
        clf.fit(np.clip((Xm - mu) / sd, -3.0, 3.0), ym, sample_weight=None if sw is None else sw[mask])
        return {"kind": "logistic", "w": clf.coef_[0].tolist(), "b": float(clf.intercept_[0]),
                "mu": mu.tolist(), "sd": sd.tolist(), "n": int(mask.sum()), "rate": float(ym.mean())}

    scorer.models["ALL"] = fit(np.ones(len(y), dtype=bool))
    for k in KINDS:
        mask = kinds_arr == k
        scorer.base_rate[k] = float(y[mask].mean()) if mask.any() else float(y.mean())
        if per_kind and mask.sum() >= min_rows and len(np.unique(y[mask])) == 2:
            scorer.models[k] = fit(mask)
    scorer.meta = {"model": model, "n": int(len(y)), "rate": float(y.mean()), "gbm_params": params if model == "gbm" else None}
    return scorer


def feature_importance(scorer: QualityScorer, rows, kinds: List[str], y: np.ndarray,
                       n_repeats: int = 3, seed: int = 0) -> List[Tuple[str, float]]:
    """Permutation importance (drop in AUC) of the pooled scorer on the given rows."""
    from sklearn.metrics import roc_auc_score
    rng = np.random.default_rng(seed)
    X = scorer.matrix(rows, kinds)
    kinds_arr = np.array(kinds)

    def auc_of(Xm: np.ndarray) -> float:
        p = np.zeros(len(Xm))
        for k in set(kinds):
            mask = kinds_arr == k
            m = scorer._model(k)
            p[mask] = 1 / (1 + np.exp(-np.clip(scorer._raw(m, Xm[mask]), -30, 30))) if m else 0.5
        return roc_auc_score(y, p)

    base = auc_of(X)
    out = []
    for j, name in enumerate(scorer.features):
        drops = []
        for _ in range(n_repeats):
            Xp = X.copy()
            Xp[:, j] = rng.permutation(Xp[:, j])
            drops.append(base - auc_of(Xp))
        out.append((name, float(np.mean(drops))))
    out.sort(key=lambda t: -t[1])
    return out


def bagged_train(rows, y: np.ndarray, kinds: List[str], n_models: int = 5, subsample: float = 0.8,
                 gbm_params: Optional[Dict] = None, seed: int = 0, scorer: Optional[QualityScorer] = None,
                 sample_weight: Optional[np.ndarray] = None) -> QualityScorer:
    """Bagged GBM: ``n_models`` boosters on random row subsets, averaged.

    The average of k boosters is itself a booster (mean baseline + every tree with
    its leaf values scaled by 1/k), so the result is exported as ONE plain ``gbm``
    model and needs no runtime change (``score`` / ``explain`` work unchanged)."""
    rng = np.random.default_rng(seed)
    y = np.asarray(y).astype(int)
    n = len(y)
    parts = []
    base_scorer = scorer if scorer is not None else QualityScorer()
    if not isinstance(rows, np.ndarray):
        rows = base_scorer.matrix(rows, kinds)      # transform once, subsample the matrix
    for k in range(n_models):
        idx = np.sort(rng.choice(n, size=int(subsample * n), replace=False))
        params = dict(gbm_params or {})
        params["random_state"] = seed * 100 + k
        sub = rows[idx] if isinstance(rows, np.ndarray) else [rows[j] for j in idx]
        s = train(sub, y[idx], [kinds[j] for j in idx], model="gbm", gbm_params=params,
                  scorer=QualityScorer(features=list(base_scorer.features)),
                  sample_weight=None if sample_weight is None else np.asarray(sample_weight)[idx])
        parts.append(s.models["ALL"])
    trees = []
    for m in parts:
        for t in m["trees"]:
            trees.append({**t, "v": [v / n_models for v in t["v"]]})
    out = QualityScorer(features=list(base_scorer.features))
    out.models["ALL"] = {"kind": "gbm", "trees": trees, "baseline": float(np.mean([m["baseline"] for m in parts])),
                         "n": n, "rate": float(y.mean()), "n_trees": len(trees), "bagged": n_models}
    kinds_arr = np.array(kinds)
    for k in KINDS:
        mask = kinds_arr == k
        out.base_rate[k] = float(y[mask].mean()) if mask.any() else float(y.mean())
    out.meta = {"model": "gbm", "bagged": n_models, "subsample": subsample, "n": n, "rate": float(y.mean()),
                "gbm_params": {**GBM_DEFAULT, **(gbm_params or {})}}
    return out



# ==============================================================================
# EXECUTION MODELS / TRADE PLANS / SIZING   (inlined from lubot/execution.py)
# ==============================================================================
# Execution layer - turn a selected POI into a concrete trade plan and size it.
#
# User specification (v7):
#
# * **Entry** = the *start* of the POI = the zone edge that price reaches first
#   (top of a bullish zone, bottom of a bearish zone) -> a LIMIT order.
# * **Stop loss** = the *end* of the POI = the far edge of the zone.
#   -> 1R = zone height (optionally + ``sl_buffer_atr`` x ATR, default 0).
# * **Partial close** at ``partial_r`` (0.4R): close ``partial_frac`` (50 %) and move
#   the stop of the remainder to break-even (``be_offset_r`` x R above/below entry,
#   default 0 = exact entry).
# * **TP2** fixed at ``tp2_r`` (1.5R) for the remainder.
#
# MT5 mechanics that matter for realism (both in the simulator and the live bot):
#
# * a BUY LIMIT is filled when the **ask** reaches the limit price, a SELL LIMIT when
#   the **bid** does; SL / TP of a long are triggered on the **bid**, of a short on
#   the **ask**.  MT5 bars are bid prices; ask = bid + spread.
# * MT5 has no native "partial take-profit".  On hedging accounts the plan is sent as
#   TWO limit orders of half the volume ("split" mode): leg A carries TP1, leg B
#   carries TP2, both carry the zone SL.  When leg A is closed by its server-side TP
#   the bot moves leg B's SL to break-even.  Server-side stops keep working even if
#   the bot loses the connection.  On netting accounts one order is sent and the bot
#   closes half at market when TP1 is touched ("netting" mode).
# * volumes are rounded DOWN to ``volume_step`` and must be >= ``volume_min``;
#   with 0.01-lot brokers the smallest tradeable plan is 0.02 lots (2 x 0.01 legs).
# * stop-outs are market executions: negative slippage ``sl_slippage`` is applied.

BUY = "buy"
SELL = "sell"


# ---------------------------------------------------------------- symbol / broker
@dataclass
class SymbolSpec:
    """Contract specification (defaults = typical XAUUSD on a 0.01-lot MT5 broker).

    ``commission_per_lot`` is the ROUND-TURN commission in account currency per
    1.0 lot (raw-spread accounts: ~$3.5 per side -> 7.0; standard accounts: 0 but a
    wider spread).  Swaps are per lot per night in account currency (negative =
    you pay); the Wednesday rollover is charged 3x.
    """
    symbol: str = "XAUUSD.t"
    digits: int = 2
    point: float = 0.01
    contract_size: float = 100.0          # 1 lot = 100 oz -> $1 move = $100 / lot
    volume_min: float = 0.01
    volume_max: float = 100.0
    volume_step: float = 0.01
    stops_level_points: int = 0           # broker minimum SL/TP distance (points)
    commission_per_lot: float = 7.0       # round turn, per 1.0 lot
    swap_long_per_lot: float = -50.0      # per night (3x on Wednesday)
    swap_short_per_lot: float = 15.0
    swap_triple_weekday: int = 2          # 0=Mon ... 2=Wed
    leverage: float = 100.0
    currency: str = "USD"

    def round_price(self, p: float) -> float:
        return round(p, self.digits)

    def round_volume_down(self, v: float) -> float:
        steps = math.floor(v / self.volume_step + 1e-9)
        vol = steps * self.volume_step
        vol = min(vol, self.volume_max)
        return round(vol, 8)

    def usd_per_price_unit(self, lots: float) -> float:
        """Account currency P/L for a $1 move of the instrument at ``lots``."""
        return lots * self.contract_size

    def margin_required(self, lots: float, price: float) -> float:
        return lots * self.contract_size * price / self.leverage


# ---------------------------------------------------------------- trader settings
@dataclass
class TraderConfig:
    # --- risk management (user spec)
    risk_pct: float = 1.0                 # % of equity risked per trade (full position, entry -> SL)
    partial_r: float = 0.4                # TP1: close partial_frac of the position here ...
    partial_frac: float = 0.5             # ... 50 %
    be_offset_r: float = 0.0              # ... and move SL to entry + be_offset_r x R
    tp2_r: float = 1.5                    # TP2 for the remainder (0 = no fixed TP2: the runner exits on trail / time / stop only)
    # --- v9 management systems (all off by default -> exactly the v7/v8 behaviour)
    tp_levels: Tuple[str, ...] = ()       # multi-target ladder in R, e.g. 0.4|1.0|2.0 ; () = partial_r / tp2_r
    tp_fracs: Tuple[str, ...] = ()        # fraction closed at each level (same length), e.g. 0.34|0.33|0.33
    be_on_partial: bool = True            # SL -> BE (be_offset_r) when the first partial closes (user spec)
    be_trigger_r: float = 0.0             # 0 = off; >0 = SL -> BE once the bar-close MFE reaches this R (works without a partial)
    ratchet_sl: bool = False              # ladder: after the k-th partial (k>=2) move SL of the rest to the (k-1)-th target
    trail_r: float = 0.0                  # 0 = off; trailing stop distance (x R) for the open legs, updated on closed M1 bars
    trail_start_r: float = 0.0            # trailing becomes active once MFE >= this R (0 = from the fill)
    trail_after_partial: bool = True      # trailing only for the runner after the first partial (False = whole position)
    trail_source: str = "extreme"         # high-water mark from the bar "extreme" or the bar "close"
    max_hold_min: int = 0                 # 0 = off; time stop - close the remaining legs at market after this many minutes
    # --- v10 multi-TP extensions (all off by default -> exactly the v9 behaviour)
    #: stop of the REMAINING legs after the k-th leg closes, in R from the entry, one entry per leg, e.g. "x|0|0.5" =
    #: nothing after leg 1, break-even after leg 2, lock +0.5R after leg 3.  "x" = leave the stop.  When set it REPLACES
    #: be_on_partial (write "0" at position 1 for the classic BE after the first leg).  Stops only ever tighten.
    sl_after_leg: Tuple[str, ...] = ()
    trail_after_leg: int = 0              # trailing (trail_r) only once this many legs have closed (0 = trail_after_partial rule)
    tp_unit: str = "r"                    # "r": targets in R (zone height) | "atr": targets in ATR of the POI's timeframe
    ladder_fallback: str = "reject"       # ladder legs below the broker minimum: "reject" the plan | "merge" them into a neighbour
    sl_buffer_atr: float = 0.0            # SL = far edge (+ buffer x ATR).  User spec: 0
    entry_offset_frac: float = 0.0        # entry = near edge moved INTO the zone by this fraction of the zone (0 = edge)
    size_on: str = "equity"               # "equity" (compounding) | "balance" (initial balance, fixed $ risk)
    # --- execution mode
    exec_mode: str = "split"              # "split" (2 half legs, server-side TPs) | "netting" (1 position, bot partial)
    market_slippage: float = 0.05         # $ adverse slippage on bot-issued market orders (netting partial close)
    sl_slippage: float = 0.10             # $ adverse slippage on stop-outs (market execution)
    spread_multiplier: float = 1.0        # stress test: widen the recorded spread
    intrabar: str = "ohlc"                # "ohlc" = MT5 tester 1-min OHLC tick path | "worst" = SL always first
    # --- order handling
    order_policy: str = "mirror"          # "mirror": pending orders follow the bot's current selection
                                          # "persist": keep a pending order until filled / expired
    max_pending_bars: int = 300           # persist: cancel after this many bars of the POI's timeframe
    max_open_positions: int = 4           # concurrent open trades (plans), all timeframes together
    max_pending_orders: int = 10
    dedupe_overlap: float = 0.5           # skip a new plan if its zone overlaps >= this fraction with an active plan's zone
    # --- v11 "more trades" levers (defaults = exactly the v10 behaviour)
    dedupe_cross_tf: bool = True          # False: the overlap check only looks at active plans of the SAME timeframe
                                          #        (a level seen on two timeframes = confluence -> both may be traded)
    overlap_mode: str = "skip"            # what to do with a plan that overlaps an active plan: "skip" (v10) |
                                          # "allow" (trade it at full risk) | "share" (trade it at risk_pct x overlap_risk_frac)
    overlap_risk_frac: float = 0.5        # share mode: risk fraction of the overlapping (second) plan
    cancel_grace_min: int = 0             # mirror policy: keep a pending order this many MINUTES after the scanner stops
                                          # showing / replaces its POI (re-shown in time -> kept).  0 = cancel at once (v10)
    # --- v12 "more trades, round 2" levers (defaults = exactly the v11 behaviour)
    #: alternative trade-filter string (same syntax as ``trade_filter``) used INSTEAD of ``trade_filter`` when the plan's
    #: zone overlaps (>= dedupe_overlap) an active plan (pending or open, same side) of ANOTHER timeframe = confluence.
    #: "" = no special treatment.  Only meaningful with dedupe_cross_tf=false (otherwise the overlap is skipped anyway).
    confluence_filter: str = ""
    #: mirror policy: an order whose POI is REPLACED by another POI on the same (tf, side) slot is kept for this many bars
    #: of its timeframe instead of being cancelled at once (re-shown in time -> kept for good).  'no longer shown' (clear)
    #: still cancels immediately.  0 = cancel at once (v11)
    keep_replaced_bars: int = 0
    keep_replaced_tfs: Tuple[str, ...] = ()   # () = every timeframe; e.g. M10|M15|M30 = only orders of these TFs are kept
    #: after a position closes at break-even (outcome in ``reentry_outcomes``) re-arm the SAME plan (entry / SL / targets)
    #: as a fresh pending limit order for this many bars of its timeframe, at most ``reentry_max`` times per POI.  0 = off
    reentry_bars: int = 0
    reentry_max: int = 1
    reentry_tfs: Tuple[str, ...] = ()         # () = every timeframe; e.g. M10|M15 = re-arm only plans of these TFs
    reentry_outcomes: Tuple[str, ...] = ("partial_be", "be")
    # --- v13 "weak months" levers (defaults = exactly the v12 behaviour) -------------------------------------------
    #: regime metric from CLOSED daily bars (lubot/regime.py): "" = off | adr_ratio (mean daily range of the last
    #: regime_short days / last regime_long days) | er (efficiency ratio of the closes over regime_short days) |
    #: adr_pct (mean daily range % of the last regime_long days).  The regime is "range" when metric < regime_threshold.
    regime_metric: str = ""
    regime_threshold: float = 0.0
    regime_short: int = 5
    regime_long: int = 20
    #: management used for plans PLACED in a "range" regime (empty = same as the normal one):
    range_tp_levels: Tuple[str, ...] = ()     # alternative ladder levels (R), e.g. 0.5|1.0|1.5|2.5
    range_tp_fracs: Tuple[str, ...] = ()      # alternative ladder fractions
    range_sl_after_leg: Tuple[str, ...] = ()  # alternative stop schedule after each leg (see sl_after_leg)
    range_risk_scale: float = 1.0             # sizing multiplier in the range regime (1 = unchanged, 0 = do not trade)
    range_tfs: Tuple[str, ...] = ()           # () = every timeframe; else only plans of these TFs use the range management
    # ---- v14 martingale A: sequence sizing (lubot/martingale.py).  "" = off (byte-identical to v13)
    mart_mode: str = ""                       # "" | mult | add | fib | deficit | anti
    mart_mult: float = 1.5                    # step multiplier (mult / anti) or 1 + slope (add); < 1 with mult = shrink after losses
    mart_max_steps: int = 3                   # k is capped here (deficit: give up after this many recovery trades)
    mart_max_risk_pct: float = 3.0            # the plan's risk in % of equity is capped here (0 = no cap)
    mart_loss_r: float = 0.2                  # a closed plan counts as a LOSS when r_net <= -this (BE exits are neutral)
    mart_deficit_r: float = 1.0               # deficit mode: recover the deficit with a trade expected to earn this many R
    mart_scope: str = "all"                   # "all" = one streak for the account | "tf" = one streak per timeframe
    mart_tfs: Tuple[str, ...] = ()            # gates: only plans of these TFs / sides / quality / regime are stepped up
    mart_sides: Tuple[str, ...] = ()
    mart_min_quality: float = 0.0
    mart_regime: str = ""                     # "" | range | trend
    mart_ungated_scale: float = 1.0           # ASYMMETRIC: an after-loss plan (k >= 1) that FAILS a gate is sized x this (e.g. 0.5 = step
                                              # down where the post-loss edge is negative); 1 = unchanged (classic gate)
    mart_tp_levels: Tuple[str, ...] = ()      # alternative ladder for the stepped-up (recovery) plans
    mart_tp_fracs: Tuple[str, ...] = ()
    mart_sl_after_leg: Tuple[str, ...] = ()
    # ---- v14 martingale B: zone-averaging grid (a second limit deeper in the zone).  0 = off
    grid_add_r: float = 0.0                   # deep leg's limit = entry + grid_add_r x (sl - entry), i.e. this fraction into the zone
    grid_base_frac: float = 0.5               # share of the plan's risk budget on the EDGE leg
    grid_add_frac: float = 0.5                # share of the budget on the DEEP leg (base + add < 1 -> a stopped plan loses < 1 R)
    grid_tfs: Tuple[str, ...] = ()            # () = every timeframe
    grid_regime: str = ""                     # "" | range | trend: only plans placed in this regime get a deep leg
    grid_cancel_on_partial: bool = True       # cancel the deep order once the edge leg has closed its first target
    grid_deep_ladder: str = "same"            # "same" = the deep leg's targets are the edge leg's prices | "own" = its own R ladder
    one_trade_per_poi: bool = True
    min_quality: Optional[float] = None   # extra filter on top of the scanner's min_quality (None = scanner default)
    grades: Tuple[str, ...] = ()          # e.g. ("A", "B") -> only these grades; () = all
    timeframes: Tuple[str, ...] = ()      # () = every timeframe in the selection stream
    sides: Tuple[str, ...] = ("buy", "sell")
    max_zone_atr: float = 0.0             # skip zones taller than this (x ATR); 0 = off
    min_zone_usd: float = 0.0             # skip zones thinner than this ($); 0 = off
    #: v8 per-timeframe trade filter (lubot/trade_filter.py), e.g.
    #: "M5:max_cost_r=0.08;min_quality=0.55;sessions=london|preny|ny|lclose".  "" = v7 behaviour
    trade_filter: str = ""
    # --- account
    balance: float = 10_000.0
    margin_buffer: float = 0.8            # use at most this share of free margin for new orders
    stop_out_level: float = 0.5           # margin level (equity / margin) below which everything is closed
    friday_close_hour_server: Optional[int] = None   # e.g. 23 -> flatten & cancel before the weekend (None = off)
    # --- v10 account protection (user spec): 0 = off
    max_daily_loss_pct: float = 0.0       # equity (realised + floating) <= day-start balance x (1 - x%) -> flatten, cancel, no new
                                          # orders until the next server day
    max_total_loss_pct: float = 0.0       # equity <= start balance x (1 - x%) -> flatten, cancel, HALT for good

    def override(self, text: Optional[str]) -> "TraderConfig":
        """key=value,key=value (tuples use a|b).  Returns self."""
        if not text:
            return self
        for pair in text.split(","):
            if not pair.strip():
                continue
            k, v = pair.split("=", 1)
            k = k.strip()
            if not hasattr(self, k):
                raise ValueError(f"unknown trader key {k}")
            cur = getattr(self, k)
            v = v.strip()
            if isinstance(cur, bool):
                val = v.lower() in ("1", "true", "yes")
            elif isinstance(cur, int) and not isinstance(cur, bool):
                val = int(v)
            elif isinstance(cur, float):
                val = float(v)
            elif isinstance(cur, tuple):
                val = tuple(x.strip() for x in v.split("|") if x.strip())
            elif cur is None:
                val = None if v.lower() in ("none", "") else (float(v) if k == "min_quality" else int(v))
            else:
                val = v
            setattr(self, k, val)
        return self

    def to_dict(self) -> Dict:
        return asdict(self)


# ---------------------------------------------------------------- trade plan
@dataclass
class TradePlan:
    side: str                     # buy / sell
    entry: float                  # limit price
    sl: float                     # initial stop (far edge)
    tp1: float                    # partial-close level
    tp2: float                    # final target
    be_price: float               # stop after the partial close
    risk: float                   # 1R in price units (|entry - sl|)
    zone_top: float
    zone_bottom: float
    tf: str = ""
    poi_id: int = -1
    kind: str = ""
    quality: float = float("nan")
    grade: str = ""
    atr: float = float("nan")
    selected_time: str = ""
    partial_frac: float = 0.5
    comment: str = ""
    tps: Tuple[float, ...] = ()   # target price of every leg (last leg: tp2, 0.0 = none)
    fracs: Tuple[float, ...] = () # fraction of every leg
    risk_scale: float = 1.0       # v11: sizing multiplier (overlap_mode=share -> overlap_risk_frac)
    reentry_n: int = 0            # v12: 0 = original plan, k = k-th re-entry of the same POI (key gets a '~k' suffix)
    confluent: bool = False       # v12: the plan passed through the confluence_filter (level active on another TF)
    regime: str = ""              # v13: "range" | "trend" | "" (regime lever off) at placement time
    sl_after_leg: Tuple[str, ...] = ()   # v13: per-plan stop schedule (empty = TraderConfig.sl_after_leg)
    mart_step: int = 0            # v14: martingale step this plan was sized with (0 = base size)
    mart_scale: float = 1.0       # v14: the sizing multiplier applied on top of risk_scale
    grid_leg: bool = False        # v14: True = this plan is the DEEP leg of a zone-averaging grid
    grid_parent: str = ""         # v14: key of the edge plan the deep leg belongs to

    # ---------------------------------------------------------- helpers
    @property
    def is_buy(self) -> bool:
        return self.side == BUY

    @property
    def key(self) -> str:
        return f"{self.tf}#{self.poi_id}" + (f"~{self.reentry_n}" if self.reentry_n else "") + ("+g" if self.grid_leg else "")

    @property
    def poi_key(self) -> str:
        """Key of the POI itself (identical for the original plan and its re-entries)."""
        return f"{self.tf}#{self.poi_id}"

    def r_of(self, price: float) -> float:
        """Signed R multiple of ``price`` relative to entry (positive = in profit)."""
        if self.risk <= 0:
            return 0.0
        return (price - self.entry) / self.risk if self.is_buy else (self.entry - price) / self.risk

    def overlaps(self, other: "TradePlan") -> float:
        """Fraction of the smaller zone covered by the other zone (0..1)."""
        lo = max(self.zone_bottom, other.zone_bottom)
        hi = min(self.zone_top, other.zone_top)
        if hi <= lo:
            return 0.0
        smaller = min(self.zone_top - self.zone_bottom, other.zone_top - other.zone_bottom)
        return (hi - lo) / smaller if smaller > 0 else 1.0

    def to_dict(self) -> Dict:
        return asdict(self)

    # ---------------------------------------------------------- construction
    @classmethod
    def from_poi(cls, d: Dict, tcfg: TraderConfig, spec: Optional[SymbolSpec] = None,
                 selected_time: str = "", regime: str = "") -> Optional["TradePlan"]:
        """Build the plan from a POI dict as returned by ``TimeframeEngine.select()``.

        bullish POI -> BUY LIMIT at the top (start) of the zone, SL at the bottom (end);
        bearish POI -> SELL LIMIT at the bottom, SL at the top.
        Returns ``None`` when the zone is degenerate (zero height).
        """
        spec = spec or SymbolSpec()
        top, bottom = float(d["top"]), float(d["bottom"])
        height = top - bottom
        if height <= 0:
            return None
        atr = float(d.get("atr") or float("nan"))
        if not math.isfinite(atr) or atr <= 0:
            # distance / distance_atr are always present on a selection dict
            da = d.get("distance_atr") or 0.0
            atr = float(d["distance"]) / da if da else float("nan")
        buf = (tcfg.sl_buffer_atr * atr) if (math.isfinite(atr) and tcfg.sl_buffer_atr > 0) else 0.0
        bull = d["direction"] == "bullish"
        if bull:
            entry = top - tcfg.entry_offset_frac * height
            sl = bottom - buf
        else:
            entry = bottom + tcfg.entry_offset_frac * height
            sl = top + buf
        risk = abs(entry - sl)
        if risk <= 0:
            return None
        sgn = 1.0 if bull else -1.0
        rp = spec.round_price
        use_range = regime == "range" and (not tcfg.range_tfs or str(d.get("tf", "")) in tcfg.range_tfs)
        levels, fracs = ladder(tcfg, range_regime=use_range)
        # v10: target unit - R (zone height, default) or the POI timeframe's ATR (falls back to R when ATR is unknown)
        unit = atr if (tcfg.tp_unit == "atr" and math.isfinite(atr) and atr > 0) else risk
        tps = tuple(rp(entry + sgn * lv * unit) if lv > 0 else 0.0 for lv in levels)
        tp1 = entry + sgn * (levels[0] if len(levels) > 1 else tcfg.partial_r) * unit
        tp2 = entry + sgn * tcfg.tp2_r * unit if len(levels) <= 1 else (tps[-1] or entry + sgn * levels[-2] * unit)
        be = entry + sgn * tcfg.be_offset_r * risk
        q = d.get("quality")
        return cls(
            side=BUY if bull else SELL,
            entry=rp(entry), sl=rp(sl), tp1=rp(tp1), tp2=rp(tp2), be_price=rp(be),
            risk=abs(rp(entry) - rp(sl)),
            zone_top=top, zone_bottom=bottom,
            tf=str(d.get("tf", "")), poi_id=int(d.get("id", -1)), kind=str(d.get("type", "")),
            quality=float(q) if q is not None else float("nan"), grade=str(d.get("grade") or ""),
            atr=atr, selected_time=selected_time or str(d.get("time", "")),
            partial_frac=fracs[0] if len(fracs) > 1 else 0.0,
            comment=f"LU {d.get('tf', '')} {d.get('type', '')} #{d.get('id', '')}",
            tps=tps, fracs=tuple(fracs),
            regime=("range" if use_range else ("trend" if regime else "")),
            sl_after_leg=tuple(tcfg.range_sl_after_leg) if (use_range and tcfg.range_sl_after_leg) else (),
            risk_scale=(tcfg.range_risk_scale if use_range else 1.0),
        )


def _retarget(plan: TradePlan, levels: Tuple[float, ...], fracs: Tuple[float, ...], spec: SymbolSpec,
              unit: Optional[float] = None) -> None:
    """Rewrite the plan's targets in place from an (R levels, fractions) ladder.  ``unit`` = 1R in price (default plan.risk)."""
    sgn = 1.0 if plan.is_buy else -1.0
    u = unit if unit else plan.risk
    rp = spec.round_price
    tps = tuple(rp(plan.entry + sgn * lv * u) if lv > 0 else 0.0 for lv in levels)
    plan.tps, plan.fracs = tps, tuple(fracs)
    plan.tp1 = rp(plan.entry + sgn * levels[0] * u)
    if len(levels) > 1:
        plan.tp2 = tps[-1] if tps[-1] else rp(plan.entry + sgn * levels[-2] * u)
    else:
        plan.tp2 = tps[-1]
    plan.partial_frac = fracs[0] if len(fracs) > 1 else 0.0


def apply_mart_ladder(plan: TradePlan, tcfg: TraderConfig, spec: SymbolSpec) -> None:
    """v14: a stepped-up (recovery) plan may use its own ladder / stop schedule (``mart_tp_levels`` ...)."""
    if plan.mart_step <= 0 or not tcfg.mart_tp_levels:
        return
    levels = tuple(float(x) for x in tcfg.mart_tp_levels)
    fr = tuple(float(x) for x in tcfg.mart_tp_fracs) if tcfg.mart_tp_fracs else tuple([1.0 / len(levels)] * len(levels))
    if len(levels) != len(fr):
        raise ValueError("mart_tp_levels and mart_tp_fracs must have the same length")
    tot = sum(fr)
    _retarget(plan, levels, tuple(f / tot for f in fr), spec)
    if tcfg.mart_sl_after_leg:
        plan.sl_after_leg = tuple(tcfg.mart_sl_after_leg)


def grid_deep_plan(edge: TradePlan, tcfg: TraderConfig, spec: SymbolSpec) -> Optional[TradePlan]:
    """v14 zone-averaging: the DEEP leg of ``edge`` - a limit ``grid_add_r`` of the way from the entry to the stop, the SAME
    stop, the same target PRICES (``grid_deep_ladder=same``: the deep leg exits with the edge leg) or its own R ladder from its
    own (shorter) risk (``own``).  Its risk budget share is ``grid_add_frac`` (the edge leg carries ``grid_base_frac``)."""
    from dataclasses import replace
    sgn = 1.0 if edge.is_buy else -1.0
    rp = spec.round_price
    entry = rp(edge.entry - sgn * tcfg.grid_add_r * edge.risk)
    risk = abs(entry - edge.sl)
    if risk <= 0 or (edge.is_buy and entry <= edge.sl) or ((not edge.is_buy) and entry >= edge.sl):
        return None
    deep = replace(edge, entry=entry, risk=risk, grid_leg=True, grid_parent=edge.key, reentry_n=edge.reentry_n,
                   risk_scale=(edge.risk_scale if edge.risk_scale > 0 else 1.0) * tcfg.grid_add_frac / max(tcfg.grid_base_frac, 1e-9),
                   comment=edge.comment + " deep", partial_frac=edge.partial_frac, be_price=rp(entry + sgn * tcfg.be_offset_r * risk))
    deep.confluent = edge.confluent
    if tcfg.grid_deep_ladder == "own":
        # the edge ladder expressed in R of the EDGE, rebuilt from the deep entry with the deep (shorter) risk as the unit
        lv = tuple(round(abs(tp - edge.entry) / edge.risk, 6) if tp > 0 else 0.0 for tp in edge.tps)
        _retarget(deep, lv, edge.fracs, spec)
    # "same": tps / tp1 / tp2 are inherited as prices -> the deep leg exits together with the edge leg
    return deep


def ladder(tcfg: TraderConfig, range_regime: bool = False) -> Tuple[Tuple[float, ...], Tuple[float, ...]]:
    """(R levels, fractions) of the legs.  Default = (partial_r, tp2_r) / (partial_frac, 1 - partial_frac);
    ``partial_frac = 0`` -> a single leg at tp2_r; ``tp_levels`` / ``tp_fracs`` -> arbitrary ladder.
    A level of 0 means "no fixed target" (only allowed for the last leg).
    v13 ``range_regime=True``: ``range_tp_levels`` / ``range_tp_fracs`` replace the normal ladder when set."""
    tp_levels, tp_fracs = tcfg.tp_levels, tcfg.tp_fracs
    if range_regime and tcfg.range_tp_levels:
        tp_levels = tcfg.range_tp_levels
        tp_fracs = tcfg.range_tp_fracs or ()
    if tp_levels:
        levels = tuple(float(x) for x in tp_levels)
        fracs = tuple(float(x) for x in tp_fracs) if tp_fracs else tuple([1.0 / len(levels)] * len(levels))
        if len(levels) != len(fracs):
            raise ValueError("tp_levels and tp_fracs must have the same length")
        tot = sum(fracs)
        fracs = tuple(f / tot for f in fracs)
        return levels, fracs
    if tcfg.partial_frac <= 0:
        return (tcfg.tp2_r,), (1.0,)
    return (tcfg.partial_r, tcfg.tp2_r), (tcfg.partial_frac, 1.0 - tcfg.partial_frac)


# ---------------------------------------------------------------- sizing
@dataclass
class Sizing:
    lots_total: float
    lots_leg1: float      # closed at TP1 (partial)
    lots_leg2: float      # runs to TP2 (sum of all further legs)
    risk_money: float     # money at risk at the initial stop (entry -> SL, without costs)
    reason: str = ""      # non-empty when the plan cannot be traded
    lots_legs: Tuple[float, ...] = ()   # per-leg volumes (ladder); len 1 or 2 in the v7/v8 plans

    @property
    def ok(self) -> bool:
        return self.lots_total > 0 and not self.reason


def size_plan(plan: TradePlan, equity: float, tcfg: TraderConfig, spec: SymbolSpec) -> Sizing:
    """Risk ``risk_pct`` % of ``equity`` between entry and the initial stop.

    Volumes are rounded DOWN to the broker step.  In split mode both legs must be
    at least ``volume_min``; if the account is too small for two legs the plan is
    rejected (never over-risk silently).
    """
    if plan.risk <= 0:
        return Sizing(0, 0, 0, 0, "zero risk")
    risk_money = equity * tcfg.risk_pct / 100.0 * (plan.risk_scale if plan.risk_scale > 0 else 1.0) \
        * (plan.mart_scale if plan.mart_scale > 0 else 1.0)
    per_unit = spec.usd_per_price_unit(1.0) * plan.risk      # $ lost per 1.0 lot at the stop
    lots = spec.round_volume_down(risk_money / per_unit) if per_unit > 0 else 0.0
    if lots < spec.volume_min:
        return Sizing(0, 0, 0, 0, f"risk {risk_money:.2f} too small for {spec.volume_min} lots (1R = {plan.risk:.2f})")
    fracs = plan.fracs if len(plan.fracs) > 2 else ()
    if fracs:
        # ladder with 3+ legs: round every leg down, the last leg takes the remainder
        legs = [spec.round_volume_down(lots * f) for f in fracs[:-1]]
        legs.append(spec.round_volume_down(lots - sum(legs)))
        if any(l < spec.volume_min for l in legs) and tcfg.ladder_fallback == "merge":
            # v10: merge the un-rounded small legs into a neighbour, then round; the last non-empty leg takes the rest
            raw = merge_small_legs([lots * f for f in fracs], spec.volume_min)
            legs = [spec.round_volume_down(x) if x > 0 else 0.0 for x in raw]
            if not any(x > 0 for x in legs):
                legs = [0.0] * (len(legs) - 1) + [lots]              # whole (tiny) volume on the last target
            last = max(i for i, x in enumerate(legs) if x > 0)
            legs[last] = spec.round_volume_down(lots - sum(legs[:last] + legs[last + 1:]))
        if tcfg.exec_mode == "split" and any(0 < l < spec.volume_min for l in legs):
            return Sizing(0, 0, 0, 0, f"volume {lots} cannot be split into {len(fracs)} legs >= {spec.volume_min}")
        if tcfg.exec_mode == "split" and any(l == 0 for l in legs) and tcfg.ladder_fallback != "merge":
            return Sizing(0, 0, 0, 0, f"volume {lots} cannot be split into {len(fracs)} legs >= {spec.volume_min}")
        if tcfg.exec_mode != "split" and any(l < spec.volume_min for l in legs):
            legs = [0.0] * (len(legs) - 1) + [lots]
        tot = round(sum(legs), 8)
        return Sizing(tot, legs[0], round(tot - legs[0], 8), tot * spec.usd_per_price_unit(1.0) * plan.risk,
                      lots_legs=tuple(legs))
    leg1 = spec.round_volume_down(lots * plan.partial_frac)
    leg2 = spec.round_volume_down(lots - leg1)
    if tcfg.exec_mode == "split":
        if (plan.partial_frac > 0 and leg1 < spec.volume_min) or leg2 < spec.volume_min:
            return Sizing(0, 0, 0, 0, f"volume {lots} cannot be split into two legs >= {spec.volume_min}")
    else:
        if leg1 < spec.volume_min:      # netting: the partial close must itself be a valid volume
            leg1, leg2 = 0.0, lots
    actual_risk = (leg1 + leg2) * spec.usd_per_price_unit(1.0) * plan.risk
    return Sizing(round(leg1 + leg2, 8), leg1, leg2, actual_risk, lots_legs=(leg1, leg2) if leg1 > 0 else (leg2,))


def merge_small_legs(legs, vmin: float):
    """v10 ``ladder_fallback="merge"``: legs below the broker minimum are merged into a neighbour (the NEXT / farther
    target when there is one, else the previous) until every non-empty leg is tradeable.  The ladder keeps its
    targets - a merged leg simply has volume 0 (it is never sent).  Total volume is unchanged."""
    legs = [round(l, 8) for l in legs]
    while True:
        small = [i for i, l in enumerate(legs) if 0 < l < vmin - 1e-9]
        if not small:
            break
        i = min(small, key=lambda k: legs[k])
        nxt = [j for j in range(i + 1, len(legs)) if legs[j] > 0]
        prv = [j for j in range(i - 1, -1, -1) if legs[j] > 0]
        if not nxt and not prv:
            break
        j = nxt[0] if nxt else prv[0]
        legs[j] = round(legs[j] + legs[i], 8)
        legs[i] = 0.0
    return legs


def expected_outcomes(tcfg: TraderConfig) -> Dict[str, float]:
    """The three possible gross results of one plan in R of the FULL position."""
    f = tcfg.partial_frac
    return {
        "stop_before_partial": -1.0,
        "partial_then_breakeven": f * tcfg.partial_r + (1 - f) * tcfg.be_offset_r,
        "partial_then_tp2": f * tcfg.partial_r + (1 - f) * tcfg.tp2_r,
    }



# ==============================================================================
# v14 MARTINGALE / LOSS-RECOVERY SIZING   (inlined from lubot/martingale.py)
# ==============================================================================
# v14 - bounded, edge-aware martingale for the LU-POI trader.
#
# Two independent families, both OFF by default (``TraderConfig`` defaults keep every v13 result byte-identical):
#
# A. **Sequence sizing** (``mart_mode``): the risk of the NEXT plan depends on the closed plans before it.
#    The state is rebuilt from the closed-trade sequence alone (``Martingale.on_close`` in close order), so the live bot
#    reproduces the simulator exactly from its own closed-trade list.
#
#    * ``mult``     risk x mart_mult^k        k = consecutive LOSSES (a plan is a loss when r_net <= -mart_loss_r; break-even
#                                              exits are neutral - they neither step nor reset), reset by a win (net > 0).
#                                              mart_mult < 1 = SHRINK after losses (the anti-martingale of the diagnosis).
#    * ``add``      risk x (1 + (mart_mult-1) k)   d'Alembert: linear steps.
#    * ``fib``      risk x fib(k)              1, 2, 3, 5, 8 ... for k = 1, 2, 3, 4, 5.
#    * ``deficit``  risk = base + deficit / mart_deficit_r     recover the money lost since the last full recovery with a trade
#                                              that is expected to earn ``mart_deficit_r`` R; the deficit shrinks with every win.
#    * ``anti``     risk x mart_mult^w         w = consecutive WINS (grow after wins, back to base after a loss).
#    Bounds: ``mart_max_steps`` (k capped), ``mart_max_risk_pct`` (the plan's risk % of equity capped), and the account rules of
#    v10 (daily 4.5 %, total 9 %) stay in force.  Gates: ``mart_tfs`` / ``mart_sides`` / ``mart_min_quality`` / ``mart_regime``
#    restrict the step-up to plans whose post-loss edge is positive (diagnosis: M5 and sells after a loss are negative).
#    ``mart_scope=tf`` keeps one streak per timeframe instead of one for the account.
#    The stepped-up (recovery) plan may use its own ladder (``mart_tp_levels`` / ``mart_tp_fracs`` / ``mart_sl_after_leg``):
#    "take the money earlier" raises the probability that the recovery trade pays.
#
# B. **Zone-averaging grid** (``grid_add_r`` > 0): a price-martingale bounded by the POI zone.  Every plan is split into the
#    EDGE leg (limit at the zone edge, ``grid_base_frac`` of the risk budget) and a DEEP leg (limit ``grid_add_r`` R inside
#    the zone, ``grid_add_frac`` of the budget, same stop).  The deep leg fills on 50-67 % of the plans (median MAE of the
#    winners = 0.33 R) at a better price with a shorter stop -> more lots per $ risked; when ``grid_base_frac + grid_add_frac``
#    < 1 a fully stopped plan loses LESS than 1 R.  The deep order lives while the edge position is open and has not taken a
#    partial (``grid_cancel_on_partial``).  Implemented in ``PortfolioSimulator`` (the plan carries ``grid_leg`` / ``grid_parent``).

pass  # typing-only block removed in the single-file build

FIB = (1.0, 2.0, 3.0, 5.0, 8.0, 13.0, 21.0, 34.0, 55.0)     # fib(k) for k = 1..9 (k = 0 -> 1)


@dataclass
class MartState:
    k: int = 0              # consecutive losses (mult/add/fib/deficit) or consecutive wins (anti)
    deficit: float = 0.0    # $ lost since the last full recovery (deficit mode)
    n_recovery: int = 0     # stepped-up plans closed since the deficit began (deficit mode safety cap)
    closed: int = 0

    def to_dict(self) -> Dict:
        return {"k": self.k, "deficit": round(self.deficit, 2), "n_recovery": self.n_recovery, "closed": self.closed}


class Martingale:
    """Sequence-sizing state machine.  Feed every closed plan in CLOSE order with ``on_close``; ask ``scale`` for the next plan."""

    def __init__(self, tcfg: "TraderConfig"):
        self.tcfg = tcfg
        self.states: Dict[str, MartState] = {}

    # ------------------------------------------------------------------ state
    @property
    def on(self) -> bool:
        return bool(self.tcfg.mart_mode)

    def _key(self, tf: str) -> str:
        return tf if self.tcfg.mart_scope == "tf" else "all"

    def state(self, tf: str) -> MartState:
        return self.states.setdefault(self._key(tf), MartState())

    def on_close(self, tf: str, net: float, r_net: float, step_used: int = 0) -> None:
        """A plan closed: ``net`` $ after costs, ``r_net`` in R of the plan's budget, ``step_used`` = the step it was sized with."""
        if not self.on:
            return
        t = self.tcfg
        st = self.state(tf)
        st.closed += 1
        loss = r_net <= -t.mart_loss_r
        win = net > 0
        if t.mart_mode == "anti":
            if win:
                st.k += 1
            elif loss:
                st.k = 0
            return
        if step_used > 0:
            st.n_recovery += 1
        if loss:
            st.k += 1
            st.deficit += -net
        elif win:
            st.k = 0
            st.deficit = max(0.0, st.deficit - net)
        if t.mart_mode == "deficit":
            if st.deficit <= 0.0 or st.n_recovery >= t.mart_max_steps:
                st.deficit, st.n_recovery = 0.0, 0        # recovered, or give up after max_steps recovery trades
        elif st.k == 0:
            st.n_recovery = 0

    # ------------------------------------------------------------------ sizing
    def gated(self, plan: "TradePlan") -> bool:
        """Does this plan qualify for a step-up?"""
        t = self.tcfg
        if t.mart_tfs and plan.tf not in t.mart_tfs:
            return False
        if t.mart_sides and plan.side not in t.mart_sides:
            return False
        if t.mart_min_quality > 0 and not (plan.quality >= t.mart_min_quality):
            return False
        if t.mart_regime and plan.regime != t.mart_regime:
            return False
        return True

    def scale(self, plan: "TradePlan", equity: float) -> Tuple[float, int]:
        """(multiplier on the plan's risk money, step) for the plan placed now.  (1.0, 0) = no change."""
        t = self.tcfg
        if not self.on:
            return 1.0, 0
        st = self.state(plan.tf)
        k = min(st.k, t.mart_max_steps)
        mode = t.mart_mode
        if not self.gated(plan):
            # asymmetric martingale: a plan that fails the gate is stepped DOWN (mart_ungated_scale < 1) while a streak is on
            in_streak = (st.deficit > 0.0) if mode == "deficit" else (k > 0)
            if in_streak and t.mart_ungated_scale != 1.0 and mode != "anti":
                return max(t.mart_ungated_scale, 0.05), -1        # step -1 marks "stepped down"
            return 1.0, 0
        if mode == "deficit":
            if st.deficit <= 0.0:
                return 1.0, 0
            base_money = equity * t.risk_pct / 100.0 * (plan.risk_scale if plan.risk_scale > 0 else 1.0)
            m = 1.0 + st.deficit / (t.mart_deficit_r * base_money) if base_money > 0 else 1.0
            step = max(1, min(st.k, t.mart_max_steps))
        elif k == 0:
            return 1.0, 0
        elif mode in ("mult", "anti"):
            m, step = t.mart_mult ** k, k
        elif mode == "add":
            m, step = 1.0 + (t.mart_mult - 1.0) * k, k
        elif mode == "fib":
            m, step = FIB[min(k, len(FIB)) - 1], k
        else:
            raise ValueError(f"unknown mart_mode {mode}")
        # cap: the plan's risk % of equity (risk_pct x risk_scale x m) <= mart_max_risk_pct
        eff = t.risk_pct * (plan.risk_scale if plan.risk_scale > 0 else 1.0)
        if t.mart_max_risk_pct > 0 and eff > 0:
            m = min(m, t.mart_max_risk_pct / eff)
        m = max(m, 0.05)          # never below 5 % of the base (anti-martingale with tiny mult)
        return m, step

    def snapshot(self) -> Dict:
        return {k: v.to_dict() for k, v in self.states.items()}

    @classmethod
    def replay(cls, tcfg: "TraderConfig", closed: list) -> "Martingale":
        """Rebuild the state from a list of closed plans ``(tf, net, r_net, step_used)`` in close order (live bot)."""
        m = cls(tcfg)
        for tf, net, r_net, step in closed:
            m.on_close(tf, float(net), float(r_net), int(step or 0))
        return m


def grid_wanted(plan: "TradePlan", tcfg: "TraderConfig") -> bool:
    """Does this plan get a deep (zone-averaging) leg?"""
    if tcfg.grid_add_r <= 0 or getattr(plan, "grid_leg", False):
        return False
    if not (0.0 < tcfg.grid_add_r < 1.0):
        raise ValueError("grid_add_r must be inside (0, 1): a fraction of the zone between the entry and the stop")
    if tcfg.grid_tfs and plan.tf not in tcfg.grid_tfs:
        return False
    if tcfg.grid_regime and plan.regime != tcfg.grid_regime:
        return False
    return True



# ==============================================================================
# PER-TIMEFRAME TRADE FILTER   (inlined from lubot/trade_filter.py)
# ==============================================================================
# v8 - per-timeframe TRADE FILTER shared by the portfolio simulator and the live bot.
#
# The v7 trader accepted every POI the scanner showed (quality >= 0.50).  On M5 that
# population loses money because the zones are small (the spread + commission is a big
# fraction of 1R) and because the scanner's bounce probability is not the probability
# of *this plan* working.  ``TradeFilter`` applies interpretable, per-timeframe gates
# to a plan before an order is placed:
#
# * ``max_cost_r``      - (spread + commission per oz) / 1R must be <= this
# * ``min_quality``     - scanner quality (P bounce) >= this
# * ``min_zone_atr`` / ``max_zone_atr`` - zone height in ATR of the timeframe
# * ``sessions``        - NY sessions allowed for the *selection* time (asia, london, preny, ny, lclose, nypm)
# * ``sides`` / ``kinds`` - buy/sell, OB/IMB/UW/HB/BB
# * ``model_path`` / ``model_min`` - optional trade-outcome model (train_trade_filter.py) score >= model_min
#
# Rules are given as a string so they fit the existing ``--trader`` CLI style (timeframe blocks
# separated by ``/`` because ``,`` already separates ``--trader`` overrides)::
#
#     "M5:max_cost_r=0.08;min_quality=0.55;sessions=london|preny|ny|lclose/M10:max_cost_r=0.10"
#
# Unlisted timeframes are unfiltered (v7 behaviour).  ``describe()`` prints the active rules.
# Everything a rule needs is already on the selection dict the scanner returns (quality,
# top/bottom, atr, type, direction, time) plus the current spread from the broker.

#: server time is NY + 7h all year for EET brokers (see StrategyConfig.server_minus_ny_hours)
SERVER_MINUS_NY_HOURS = 7.0
EST_COMMISSION_OZ = 0.07     # $7 / lot round turn / 100 oz


@dataclass
class TFRule:
    max_cost_r: float = 0.0            # 0 = off
    min_quality: float = 0.0
    min_zone_atr: float = 0.0
    max_zone_atr: float = 0.0
    sessions: Tuple[str, ...] = ()
    sides: Tuple[str, ...] = ()
    kinds: Tuple[str, ...] = ()
    model_path: str = ""
    model_min: float = 0.0
    hours: Tuple[int, ...] = ()        # allowed NY hours of the selection time (empty = all)

    def active(self) -> bool:
        return any([self.max_cost_r, self.min_quality, self.min_zone_atr, self.max_zone_atr, self.sessions, self.sides,
                    self.kinds, self.model_path, self.hours])

    def describe(self) -> str:
        parts = []
        for k in ("max_cost_r", "min_quality", "min_zone_atr", "max_zone_atr", "model_min"):
            v = getattr(self, k)
            if v:
                parts.append(f"{k}={v}")
        for k in ("sessions", "sides", "kinds", "hours"):
            v = getattr(self, k)
            if v:
                parts.append(f"{k}={'|'.join(str(x) for x in v)}")
        if self.model_path:
            parts.append(f"model={self.model_path}")
        return ";".join(parts) or "none"


def ny_session_of(ts, server_minus_ny_hours: float = SERVER_MINUS_NY_HOURS) -> Tuple[str, int]:
    """NY session name + NY hour of a server-time timestamp."""
    t = pd.Timestamp(ts) - pd.Timedelta(hours=server_minus_ny_hours)
    return session_of(t.hour), int(t.hour)


class TradeFilter:
    def __init__(self, rules: Optional[Dict[str, TFRule]] = None, spread_estimate: float = 0.28,
                 commission_oz: float = EST_COMMISSION_OZ, server_minus_ny_hours: float = SERVER_MINUS_NY_HOURS):
        self.rules: Dict[str, TFRule] = rules or {}
        self.spread_estimate = spread_estimate
        self.commission_oz = commission_oz
        self.server_minus_ny = server_minus_ny_hours
        self._models: Dict[str, QualityScorer] = {}

    # ----------------------------------------------------------------- parsing
    @classmethod
    def parse(cls, text: Optional[str], **kw) -> "TradeFilter":
        """'M5:max_cost_r=0.08;min_quality=0.55;sessions=london|ny/M10:max_cost_r=0.1' -> TradeFilter"""
        rules: Dict[str, TFRule] = {}
        if text:
            for block in text.replace(",", "/").split("/"):
                block = block.strip()
                if not block:
                    continue
                tf, _, body = block.partition(":")
                tf = tf.strip()
                if not body:
                    raise ValueError(f"trade-filter block '{block}' needs 'TF:key=value;...'")
                for tfi in (tf.split("|") if tf != "*" else ["*"]):
                    r = rules.setdefault(tfi, TFRule())
                    for pair in body.split(";"):
                        if not pair.strip():
                            continue
                        k, _, v = pair.partition("=")
                        k, v = k.strip(), v.strip()
                        if not hasattr(r, k):
                            raise ValueError(f"unknown trade-filter key {k}")
                        cur = getattr(r, k)
                        if isinstance(cur, tuple):
                            vals = tuple(x.strip() for x in v.split("|") if x.strip())
                            setattr(r, k, tuple(int(x) for x in vals) if k == "hours" else vals)
                        elif isinstance(cur, float):
                            setattr(r, k, float(v))
                        else:
                            setattr(r, k, v)
        return cls(rules, **kw)

    def rule_for(self, tf: str) -> Optional[TFRule]:
        r = self.rules.get(tf) or self.rules.get("*")
        return r if (r is not None and r.active()) else None

    def active(self) -> bool:
        return any(r.active() for r in self.rules.values())

    def describe(self) -> str:
        return ", ".join(f"{tf}: {r.describe()}" for tf, r in self.rules.items() if r.active()) or "no trade filter (v7 behaviour)"

    def to_text(self) -> str:
        return "/".join(f"{tf}:{r.describe()}" for tf, r in self.rules.items() if r.active())

    # ----------------------------------------------------------------- scoring
    def _model(self, path: str) -> Optional[QualityScorer]:
        m = self._models.get(path)
        if m is None and path:
            m = QualityScorer.load(path)
            self._models[path] = m
        return m

    def cost_r(self, top: float, bottom: float, spread: Optional[float]) -> float:
        risk = abs(float(top) - float(bottom))
        sp = self.spread_estimate if (spread is None or not math.isfinite(spread)) else float(spread)
        return (sp + self.commission_oz) / risk if risk > 0 else float("inf")

    def check(self, d: Dict, tf: str, spread: Optional[float] = None, when=None) -> Optional[str]:
        """Return None when the plan passes, else the reason it is rejected.

        ``d`` = selection dict of the POI (top, bottom, quality, type, direction, atr, time, and
        optionally ``features``/``context``/``feats`` for the model).  ``when`` = selection time (server);
        defaults to d["time"]."""
        r = self.rule_for(tf)
        if r is None:
            return None
        top, bottom = float(d["top"]), float(d["bottom"])
        if r.max_cost_r:
            c = self.cost_r(top, bottom, spread)
            if c > r.max_cost_r:
                return f"cost_r {c:.3f} > {r.max_cost_r}"
        q = d.get("quality")
        if r.min_quality and not (q is not None and float(q) >= r.min_quality):
            return f"quality {q} < {r.min_quality}"
        atr = d.get("atr")
        if (r.min_zone_atr or r.max_zone_atr) and atr and float(atr) > 0:
            za = (top - bottom) / float(atr)
            if r.min_zone_atr and za < r.min_zone_atr:
                return f"zone {za:.2f} ATR < {r.min_zone_atr}"
            if r.max_zone_atr and za > r.max_zone_atr:
                return f"zone {za:.2f} ATR > {r.max_zone_atr}"
        side = "buy" if d.get("direction") == "bullish" else "sell"
        if r.sides and side not in r.sides:
            return f"side {side}"
        if r.kinds and d.get("type") not in r.kinds:
            return f"kind {d.get('type')}"
        if r.sessions or r.hours:
            ts = when if when is not None else d.get("time")
            if ts is not None:
                sess, hour = ny_session_of(ts, self.server_minus_ny)
                if r.sessions and sess not in r.sessions:
                    return f"session {sess}"
                if r.hours and hour not in r.hours:
                    return f"ny hour {hour}"
        if r.model_path:
            m = self._model(r.model_path)
            feats = d.get("feats") or {**d.get("features", {}), **d.get("context", {})}
            if m is None or not feats:
                return "model features missing"
            z = max(top - bottom, 0.01)
            feats = {**feats, "zone_usd": z, "cost_r_est": (self.spread_estimate + self.commission_oz) / z}
            p = m.score(str(d.get("type", "")), feats)
            d["filter_score"] = round(float(p), 4)
            if p < r.model_min:
                return f"filter score {p:.3f} < {r.model_min}"
        return None



# ==============================================================================
# v13 MARKET REGIME   (inlined from lubot/regime.py)
# ==============================================================================
# v13 - market REGIME from closed daily bars (shared by the simulator and the live bot).
#
# The v13 diagnosis (study_results/WEAK_MONTHS_V13.md) showed that the negative month of the v12-A trader (Apr 2026) was not a
# selection problem but a MANAGEMENT problem: in a post-crash range the far legs of the 0.6/1.2/2.4/4.8R ladder are never paid,
# the partials return to break-even and the stop-rate rises.  The bot earns with volatility (Spearman of monthly R vs average
# daily range = +0.56).  These helpers compute, from the daily bars that are already CLOSED at the moment an order is placed
# (nothing intrabar, nothing from the future), a scalar "regime metric" that the trader compares to a threshold:
#
# * ``adr_ratio`` - mean daily range of the last ``short`` days / mean daily range of the last ``long`` days
#                   (< 1 = volatility contracting)
# * ``er``        - Kaufman efficiency ratio of the daily closes over ``short`` days: |net move| / sum of |daily moves|
#                   (0 = pure chop, 1 = straight line)
# * ``adr_pct``   - mean daily range of the last ``long`` days as % of the last close (absolute volatility level)
#
# ``regime_of(metric_value, threshold)`` -> "range" when the metric is BELOW the threshold, else "trend".  The trader then
# uses the alternative ladder / stop schedule / risk scale configured for the range regime (``TraderConfig.range_*``).
#
# Server days are used as trading days (the M1 index is server time); the metric of day D is computed from the days
# < D and is valid for every minute of D.

METRICS = ("adr_ratio", "er", "adr_pct")


def daily_bars(m1: pd.DataFrame) -> pd.DataFrame:
    """Server-day OHLC from M1 bars (days without bars dropped)."""
    d = m1[["open", "high", "low", "close"]].resample("1D").agg({"open": "first", "high": "max", "low": "min", "close": "last"})
    return d.dropna(subset=["open"])


def _raw_metric(daily: pd.DataFrame, metric: str, short: int, long: int) -> pd.Series:
    """Metric of every day computed from that day and the days before it (INCLUDING the day itself)."""
    if metric not in METRICS:
        raise ValueError(f"unknown regime metric {metric!r} (use one of {METRICS})")
    rng = (daily["high"] - daily["low"]).astype(float)
    if metric == "adr_ratio":
        return rng.rolling(short).mean() / rng.rolling(long).mean()
    if metric == "er":
        c = daily["close"].astype(float)
        return c.diff(short).abs() / c.diff().abs().rolling(short).sum()
    return rng.rolling(long).mean() / daily["close"].astype(float) * 100.0      # adr_pct


def metric_series(daily: pd.DataFrame, metric: str, short: int = 5, long: int = 20) -> pd.Series:
    """Metric per day computed from the days STRICTLY BEFORE it (shift(1)) -> usable at that day's open.
    NaN while the history is too short (the trader treats NaN as 'trend' = default behaviour)."""
    return _raw_metric(daily, metric, short, long).shift(1)


def regime_of(value: float, threshold: float) -> str:
    """'range' when the metric is below the threshold, 'trend' otherwise (NaN -> 'trend')."""
    if value is None or not np.isfinite(value):
        return "trend"
    return "range" if value < threshold else "trend"


def minute_metric(m1: pd.DataFrame, metric: str, short: int = 5, long: int = 20) -> np.ndarray:
    """Metric value for every M1 bar of ``m1`` (the value of its server day)."""
    daily = daily_bars(m1)
    s = metric_series(daily, metric, short, long)
    days = m1.index.normalize()
    return s.reindex(days).to_numpy(dtype=float)


def latest_metric(daily: pd.DataFrame, metric: str, short: int = 5, long: int = 20, today: Optional[pd.Timestamp] = None) -> float:
    """Live bot: metric valid NOW from a frame of daily bars whose LAST row may be the (unfinished) current day.
    Rows dated >= ``today`` (default: the last row's day) are excluded so only CLOSED days are used."""
    d = daily
    if today is None and len(d):
        today = d.index[-1].normalize()
    if today is not None:
        d = d[d.index.normalize() < today]
    if len(d) < max(short, long) + 1:
        return float("nan")
    v = _raw_metric(d, metric, short, long).iloc[-1]
    return float(v) if np.isfinite(v) else float("nan")



# ==============================================================================
# M1 PORTFOLIO SIMULATOR (BACKTEST)   (inlined from lubot/portfolio_sim.py)
# ==============================================================================
# M1-precision portfolio simulator for the v7 trader.
#
# Replays the recorded selection stream (``record_selections.py``) on the M1 bars and
# executes every plan the way the live bot / an MT5 broker would:
#
# * pending LIMIT orders placed when a POI is selected (at the bar close time), cancelled
#   when the bot stops showing the POI ("mirror" policy) or after ``max_pending_bars``;
# * fills on the **ask** (buy) / **bid** (sell).  MT5 bars are bid; ask = bid + spread
#   (the spread of that minute - real where exported, imputed elsewhere, x ``spread_multiplier``);
# * SL / TP of a long are checked on the bid, of a short on the ask, each M1 bar walked
#   in the MT5-tester order Open -> (High/Low in the order implied by the close) -> Close;
#   when SL and TP are both inside one minute the *path* decides; ``intrabar="worst"``
#   always takes the stop;
# * partial close at TP1: leg 1 (``partial_frac``) is closed at TP1 (limit -> no
#   slippage), leg 2's stop moves to break-even in the same minute (MT5: server-side TP on
#   leg 1, bot modifies leg 2 - the modification is assumed to happen inside the minute;
#   ``be_delay_bars`` > 0 delays it to model a slow bot);
# * stop-outs are market executions -> ``sl_slippage`` against you; bot-issued market
#   orders -> ``market_slippage``;
# * commission per lot round turn, swaps per night (3x on the triple day), margin check
#   and stop-out level;
# * position sizing ``risk_pct`` of the current equity (compounding) or of the initial
#   balance, rounded down to the broker's volume step;
# * at most ``max_open_positions`` plans open, one plan per POI, overlapping zones
#   de-duplicated.
#
# Everything is bookkept in account currency and in R of the *full* position, so the
# result can be read both as "$ on a 10k account" and as "R per trade".

# ---------------------------------------------------------------------------- records
@dataclass
class Leg:
    lots: float
    tp: float                 # 0.0 = no fixed target (runner managed by trail / time stop)
    sl: float
    open: bool = True
    close_price: float = float("nan")
    close_time: Optional[pd.Timestamp] = None
    close_reason: str = ""
    pnl: float = 0.0          # gross $ (price move only)


@dataclass
class Position:
    plan: TradePlan
    lots: float
    legs: List[Leg]
    entry_time: pd.Timestamp
    entry_price: float        # actual fill (ask for buys)
    risk_money: float
    commission: float = 0.0
    swap: float = 0.0
    partial_done: bool = False
    partial_time: Optional[pd.Timestamp] = None
    be_at_minute: int = -1    # minute index at which BE becomes active (be_delay_bars)
    mfe_r: float = 0.0
    mae_r: float = 0.0
    closed: bool = False
    close_time: Optional[pd.Timestamp] = None
    outcome: str = ""         # sl | partial_be | tp2 | partial_sl_be | forced | stopout | trail | time
    n_partials: int = 0       # ladder: number of target legs already closed
    hwm: float = float("nan")  # trailing: high-water mark (price) on the closing side
    be_armed: bool = False    # be_trigger_r reached (BE active irrespective of partials)
    sl_queue: List[Tuple[int, float]] = field(default_factory=list)   # v10: (minute from which, stop) delayed stop moves

    @property
    def open_lots(self) -> float:
        return sum(l.lots for l in self.legs if l.open)


@dataclass
class Pending:
    plan: TradePlan
    placed: pd.Timestamp
    placed_minute: int
    lots_leg1: float
    lots_leg2: float
    expires_minute: int
    reason_cancel: str = ""
    lots_legs: Tuple[float, ...] = ()
    grace_until: int = -1          # v11 cancel_grace_min: cancel at this minute unless the POI is shown again before
    grace_reason: str = ""
    armed: bool = True             # v12 re-entry placed while price is through the entry: becomes a live limit order
                                   # on the first bar that opens in front of the entry again


# ---------------------------------------------------------------------------- simulator
class PortfolioSimulator:
    def __init__(self, m1: pd.DataFrame, selections: pd.DataFrame, tcfg: TraderConfig,
                 spec: Optional[SymbolSpec] = None, be_delay_bars: int = 0, start: Optional[str] = None,
                 end: Optional[str] = None):
        self.tcfg = tcfg
        self.spec = spec or SymbolSpec()
        self.be_delay = be_delay_bars
        m = m1 if start is None else m1[start:]
        m = m if end is None else m[:end]
        self.idx = m.index.values.astype("datetime64[ns]")
        self.open_ = m["open"].to_numpy(float)
        self.high = m["high"].to_numpy(float)
        self.low = m["low"].to_numpy(float)
        self.close = m["close"].to_numpy(float)
        sp = m["spread"].to_numpy(float) if "spread" in m else np.full(len(m), 0.28)
        sp = np.where(np.isfinite(sp), sp, np.nanmedian(sp))
        self.spread = sp * tcfg.spread_multiplier
        self.n = len(m)
        sel = selections.copy()
        sel = sel[(sel.t >= m.index[0]) & (sel.t <= m.index[-1] + pd.Timedelta(minutes=1))]
        if tcfg.timeframes:
            sel = sel[sel.tf.isin(tcfg.timeframes)]
        self.sel = sel.sort_values("t").reset_index(drop=True)
        # map each event to the FIRST M1 bar whose open time >= event time (act at that bar's open)
        self.sel_minute = np.searchsorted(self.idx, self.sel.t.values.astype("datetime64[ns]"), side="left")
        # state
        self.balance = tcfg.balance
        self.equity = tcfg.balance
        self.pending: Dict[str, Pending] = {}
        self.positions: Dict[str, Position] = {}
        self.closed: List[Position] = []
        self.cancelled: List[Pending] = []
        self.skipped: List[Tuple[str, str]] = []
        self.traded_pois: set = set()
        self.equity_curve: List[Tuple[np.datetime64, float, float]] = []   # (time, balance, equity)
        self.shown: Dict[Tuple[str, str], int] = {}   # (tf, side) -> currently shown poi id
        self.stopped_out = False
        # v10 account protection
        self.day_start_balance = tcfg.balance
        self.daily_halt_day: Optional[np.datetime64] = None     # server day on which the daily limit was hit
        self.halted = False                                      # total-loss limit hit -> no more trading
        self.daily_halts: List[Tuple[pd.Timestamp, float]] = []  # (time, equity) of every daily-limit event
        self.halt_time: Optional[pd.Timestamp] = None
        # v8: per-timeframe trade filter (cost / quality / session / side / kind / model gates)
        self.filter = TradeFilter.parse(tcfg.trade_filter, commission_oz=self.spec.commission_per_lot / self.spec.contract_size)
        self.filtered: List[Tuple[str, str]] = []
        # v12: alternative filter for confluence plans (zone overlaps an active plan of another timeframe)
        self.conf_filter: Optional[TradeFilter] = TradeFilter.parse(
            tcfg.confluence_filter, commission_oz=self.spec.commission_per_lot / self.spec.contract_size) \
            if tcfg.confluence_filter else None
        self.cur_minute = 0
        self.reentries_placed = 0
        # v13: regime metric per M1 bar from CLOSED daily bars (NaN -> "trend" = normal management)
        self.regime_val: Optional[np.ndarray] = None
        if tcfg.regime_metric:
            self.regime_val = minute_metric(m, tcfg.regime_metric, tcfg.regime_short, tcfg.regime_long)
        self.regime_counts: Dict[str, int] = {"range": 0, "trend": 0}
        # v14: martingale state (sequence sizing) + grid bookkeeping
        self.mart = Martingale(tcfg)
        self.grid_placed = 0
        self.grid_filled = 0

    # ------------------------------------------------------------------ helpers
    def _tf_minutes(self, tf: str) -> int:
        return TIMEFRAME_MINUTES.get(tf, 5)

    def _regime(self, minute: int) -> str:
        """v13: 'range' | 'trend' for the plan placed at ``minute`` ('' when the lever is off)."""
        if self.regime_val is None:
            return ""
        return regime_of(float(self.regime_val[minute]), self.tcfg.regime_threshold)

    def _margin_used(self, price: float) -> float:
        return sum(self.spec.margin_required(p.open_lots, price) for p in self.positions.values())

    def _floating(self, bid: float, ask: float) -> float:
        tot = 0.0
        for p in self.positions.values():
            px = bid if p.plan.is_buy else ask
            sgn = 1.0 if p.plan.is_buy else -1.0
            tot += sum(sgn * (px - p.entry_price) * l.lots * self.spec.contract_size for l in p.legs if l.open)
        return tot

    def _accept_plan(self, plan: TradePlan) -> Optional[str]:
        t = self.tcfg
        if self.halted:
            return "halted (total loss limit)"
        if self.daily_halt_day is not None:
            return "daily loss limit"
        if t.one_trade_per_poi and plan.poi_key in self.traded_pois and plan.reentry_n == 0:
            return "poi already traded"
        if plan.key in self.pending or plan.key in self.positions:
            return "already active"
        if t.sides and plan.side not in t.sides:
            return "side filtered"
        if t.grades and plan.grade not in t.grades:
            return "grade filtered"
        if t.min_quality is not None and not (plan.quality >= t.min_quality):
            return "quality filtered"
        if t.max_zone_atr and math.isfinite(plan.atr) and (plan.zone_top - plan.zone_bottom) > t.max_zone_atr * plan.atr:
            return "zone too tall"
        if t.min_zone_usd and (plan.zone_top - plan.zone_bottom) < t.min_zone_usd:
            return "zone too thin"
        if sum(1 for p in self.pending.values() if not p.plan.grid_leg) >= t.max_pending_orders:
            return "max pending"
        ov = self._overlap_kind(plan)
        if ov and t.overlap_mode == "skip":
            return f"overlaps {ov}"
        return None

    def _overlap_kind(self, plan: TradePlan) -> str:
        """'' | 'pending' | 'open': does the plan's zone overlap an active plan of the same side
        (v11 ``dedupe_cross_tf=False``: only plans of the same timeframe count)?"""
        t = self.tcfg
        for other in list(self.pending.values()):
            if other.plan.grid_leg:
                continue
            if other.plan.side == plan.side and (t.dedupe_cross_tf or other.plan.tf == plan.tf) \
                    and plan.overlaps(other.plan) >= t.dedupe_overlap:
                return "pending"
        for other in self.positions.values():
            if other.plan.grid_leg:
                continue
            if other.plan.side == plan.side and (t.dedupe_cross_tf or other.plan.tf == plan.tf) \
                    and plan.overlaps(other.plan) >= t.dedupe_overlap:
                return "open"
        return ""

    def _confluent_other_tf(self, plan: TradePlan) -> bool:
        """v12: does the plan's zone overlap (>= dedupe_overlap) an ACTIVE plan (pending or open, same side) of
        ANOTHER timeframe?  That is the confluence evidence the ``confluence_filter`` relies on."""
        t = self.tcfg
        for other in list(self.pending.values()) + list(self.positions.values()):
            if other.plan.grid_leg:
                continue
            if other.plan.side == plan.side and other.plan.tf != plan.tf and plan.overlaps(other.plan) >= t.dedupe_overlap:
                return True
        return False

    # ------------------------------------------------------------------ order events
    def _on_event(self, row, minute: int) -> None:
        key_side = (row.tf, row.side)
        prev = self.shown.get(key_side)
        if row.event == "clear" or row.id < 0:
            self.shown.pop(key_side, None)
            if prev is not None and self.tcfg.order_policy == "mirror":
                self._mirror_cancel(f"{row.tf}#{prev}", "no longer shown", minute)
                # v12 keep_replaced_bars: a clear of the slot also drops the orders kept after a 'replaced'
                if self.tcfg.keep_replaced_bars > 0:
                    side = "buy" if row.side == "below" else "sell"
                    for k, p in list(self.pending.items()):
                        if p.grace_reason == "replaced" and p.plan.tf == row.tf and p.plan.side == side and p.plan.reentry_n == 0:
                            self._cancel(k, "no longer shown", minute)
            return
        self.shown[key_side] = int(row.id)
        if prev is not None and prev != row.id and self.tcfg.order_policy == "mirror":
            self._mirror_cancel(f"{row.tf}#{prev}", "replaced", minute)
        # v11 grace: the POI is shown again while its order waits in the grace period -> keep the order
        pend = self.pending.get(f"{row.tf}#{int(row.id)}")
        if pend is not None and pend.grace_until >= 0:
            pend.grace_until, pend.grace_reason = -1, ""
        d = {"id": row.id, "tf": row.tf, "type": row.type, "direction": row.direction, "top": row.top,
             "bottom": row.bottom, "quality": None if not np.isfinite(row.quality) else row.quality,
             "grade": row.grade, "distance": row.distance, "distance_atr": row.distance_atr, "atr": row.atr,
             "time": str(row.t)}
        if "feats" in row.index and isinstance(row.feats, dict):
            d["feats"] = row.feats
        plan = TradePlan.from_poi(d, self.tcfg, self.spec, selected_time=str(row.t), regime=self._regime(minute))
        if plan is None:
            return
        if plan.regime:
            self.regime_counts[plan.regime] = self.regime_counts.get(plan.regime, 0) + 1
        if plan.regime == "range" and self.tcfg.range_risk_scale <= 0:
            self.skipped.append((plan.key, "range regime (no trading)"))
            return
        why = self._accept_plan(plan)
        if why:
            self.skipped.append((plan.key, why))
            return
        # v8 trade filter, evaluated with the spread of the minute the order would be placed
        # (v12: a confluence plan - same level active on another timeframe - is judged by ``confluence_filter`` instead)
        flt = self.filter
        if self.conf_filter is not None and self._confluent_other_tf(plan):
            flt = self.conf_filter
            plan.confluent = True
        why = flt.check(d, row.tf, spread=float(self.spread[minute]), when=row.t)
        if why:
            self.filtered.append((plan.key, f"{row.tf}: {why.split(' ')[0]}"))
            self.skipped.append((plan.key, "trade filter"))
            return
        # v11 overlap_mode=share: an overlapping (confluence) plan is traded at a reduced risk
        if self.tcfg.overlap_mode == "share" and self._overlap_kind(plan):
            plan.risk_scale = plan.risk_scale * self.tcfg.overlap_risk_frac
        # price already through the entry? (POI selected while price is inside/beyond the zone) -> skip
        bid = self.open_[minute]
        ask = bid + self.spread[minute]
        if (plan.is_buy and ask <= plan.entry) or (not plan.is_buy and bid >= plan.entry):
            self.skipped.append((plan.key, "price already at/through entry"))
            return
        base = self.equity if self.tcfg.size_on == "equity" else self.tcfg.balance
        self._apply_v14(plan, base)
        sz = size_plan(plan, base, self.tcfg, self.spec)
        if not sz.ok:
            self.skipped.append((plan.key, sz.reason))
            return
        # margin check for the would-be position
        need = self.spec.margin_required(sz.lots_total, plan.entry)
        free = self.equity - self._margin_used(bid)
        if need > free * self.tcfg.margin_buffer:
            self.skipped.append((plan.key, "insufficient margin"))
            return
        exp_min = minute + self.tcfg.max_pending_bars * self._tf_minutes(row.tf) if self.tcfg.order_policy == "persist" else 10 ** 12
        self.pending[plan.key] = Pending(plan, pd.Timestamp(self.idx[minute]), minute, sz.lots_leg1, sz.lots_leg2, exp_min,
                                         lots_legs=sz.lots_legs)
        self._place_deep(plan, base, minute, exp_min)

    # ------------------------------------------------------------------ v14 martingale / grid
    def _apply_v14(self, plan: TradePlan, base: float) -> None:
        """Sequence sizing: scale the plan's risk from the closed-trade streak; the recovery plan may get its own ladder.
        Grid: the EDGE leg carries ``grid_base_frac`` of the budget."""
        tc = self.tcfg
        if self.mart.on:
            m, step = self.mart.scale(plan, base)
            plan.mart_scale, plan.mart_step = m, step
            apply_mart_ladder(plan, tc, self.spec)
        if grid_wanted(plan, tc):
            plan.risk_scale = (plan.risk_scale if plan.risk_scale > 0 else 1.0) * tc.grid_base_frac

    def _place_deep(self, edge: TradePlan, base: float, minute: int, exp_min: int) -> None:
        """Grid: place the DEEP limit order of ``edge`` (same stop, deeper entry, its share of the budget)."""
        tc = self.tcfg
        if not grid_wanted(edge, tc):
            return
        deep = grid_deep_plan(edge, tc, self.spec)
        if deep is None:
            return
        # the deep leg's risk_scale already contains add_frac / base_frac x the edge scale (edge scale includes base_frac)
        deep.mart_scale, deep.mart_step = edge.mart_scale, edge.mart_step
        sz = size_plan(deep, base, tc, self.spec)
        if not sz.ok:
            self.skipped.append((deep.key, "grid: " + sz.reason))
            return
        self.pending[deep.key] = Pending(deep, pd.Timestamp(self.idx[minute]), minute, sz.lots_leg1, sz.lots_leg2, exp_min,
                                         lots_legs=sz.lots_legs)
        self.grid_placed += 1

    def _grid_sync(self, key: str, reason: str, minute: int) -> None:
        """The edge order/position of a grid ended -> its deep order follows (cancel), unless the deep leg is already a position."""
        if self.tcfg.grid_add_r <= 0:
            return
        dk = key + "+g"
        if dk in self.pending:
            self._cancel(dk, reason, minute)

    def _cancel(self, key: str, reason: str, minute: int) -> None:
        p = self.pending.pop(key, None)
        if p is not None:
            p.reason_cancel = reason
            self.cancelled.append(p)
            if not p.plan.grid_leg:
                self._grid_sync(key, reason, minute)

    def _mirror_cancel(self, key: str, reason: str, minute: int) -> None:
        """Mirror policy cancel; with ``cancel_grace_min`` > 0 the order is only scheduled for cancellation.
        v12 ``keep_replaced_bars``: an order whose POI was merely REPLACED on its slot stays that many bars of its
        timeframe (re-shown in time -> kept); a 'no longer shown' clear still cancels at once."""
        g = self.tcfg.cancel_grace_min
        p = self.pending.get(key)
        if reason == "replaced" and self.tcfg.keep_replaced_bars > 0 and p is not None and \
                (not self.tcfg.keep_replaced_tfs or p.plan.tf in self.tcfg.keep_replaced_tfs):
            if p.grace_until < 0:
                p.grace_until = minute + self.tcfg.keep_replaced_bars * self._tf_minutes(p.plan.tf)
                p.grace_reason = reason
            return
        if g <= 0:
            self._cancel(key, reason, minute)
            return
        if p is not None and p.grace_until < 0:
            p.grace_until = minute + g
            p.grace_reason = reason

    # ------------------------------------------------------------------ v12 re-entry
    def _rearm(self, pos: Position, minute: int) -> None:
        """After a break-even exit re-arm the same plan as a fresh limit order for ``reentry_bars`` bars of its TF."""
        tc = self.tcfg
        old = pos.plan
        if old.reentry_n >= tc.reentry_max or self.halted or self.daily_halt_day is not None or self.stopped_out:
            return
        if tc.reentry_tfs and old.tf not in tc.reentry_tfs:
            return
        if len(self.pending) >= tc.max_pending_orders:
            return
        from dataclasses import replace
        plan = replace(old, reentry_n=old.reentry_n + 1, risk_scale=1.0, mart_scale=1.0, mart_step=0)
        plan.confluent = old.confluent
        if plan.key in self.pending or plan.key in self.positions:
            return
        base = self.equity if tc.size_on == "equity" else tc.balance
        self._apply_v14(plan, base)
        sz = size_plan(plan, base, tc, self.spec)
        if not sz.ok:
            self.skipped.append((plan.key, sz.reason))
            return
        bid = self.close[minute]
        ask = bid + self.spread[minute]
        need = self.spec.margin_required(sz.lots_total, plan.entry)
        free = self.equity - self._margin_used(bid)
        if need > free * tc.margin_buffer:
            self.skipped.append((plan.key, "insufficient margin"))
            return
        # the position was just stopped at break-even -> price is at / through the entry: the limit order only becomes
        # live once a bar opens in front of the entry again (MT5 would reject a buy limit above the ask)
        armed = (ask > plan.entry) if plan.is_buy else (bid < plan.entry)
        exp = minute + tc.reentry_bars * self._tf_minutes(plan.tf)
        self.pending[plan.key] = Pending(plan, pd.Timestamp(self.idx[minute]), minute, sz.lots_leg1, sz.lots_leg2, exp,
                                         lots_legs=sz.lots_legs, armed=armed)
        self.reentries_placed += 1

    # ------------------------------------------------------------------ fills
    def _try_fill(self, pend: Pending, minute: int) -> Optional[Position]:
        plan = pend.plan
        sp = self.spread[minute]
        if not pend.armed:
            # v12 re-entry waiting for the price to be back in front of the entry (checked at the bar's open)
            if (plan.is_buy and self.open_[minute] + sp > plan.entry) or (not plan.is_buy and self.open_[minute] < plan.entry):
                pend.armed = True
            else:
                return None
        if plan.is_buy:
            # ask path: open_ask, low_ask ... filled if low ask <= limit
            if self.low[minute] + sp > plan.entry:
                return None
            fill = min(plan.entry, self.open_[minute] + sp)        # gap through the limit -> better price
        else:
            if self.high[minute] < plan.entry:
                return None
            fill = max(plan.entry, self.open_[minute])
        if plan.grid_leg:
            # v14 deep leg: belongs to the edge plan -> does not take a slot; only fills while the edge plan is still alive
            if plan.grid_parent not in self.positions and plan.grid_parent not in self.pending:
                self._cancel(plan.key, "edge plan gone", minute)
                return None
        elif sum(1 for p in self.positions.values() if not p.plan.grid_leg) >= self.tcfg.max_open_positions:
            self._cancel(plan.key, "max open positions at fill time", minute)
            return None
        fill = self.spec.round_price(fill)
        lots = pend.lots_leg1 + pend.lots_leg2
        legs = []
        if len(plan.tps) > 2 and pend.lots_legs:
            # v9 ladder (3+ legs) - always split legs with server-side targets
            for lv, tp in zip(pend.lots_legs, plan.tps):
                if lv > 0:
                    legs.append(Leg(lv, tp, plan.sl))
        elif self.tcfg.exec_mode == "netting":
            legs.append(Leg(round(lots, 8), plan.tp2 if self.tcfg.tp2_r > 0 else 0.0, plan.sl))   # one position; bot closes the partial at market
        else:
            if pend.lots_leg1 > 0:
                legs.append(Leg(pend.lots_leg1, plan.tp1, plan.sl))
            legs.append(Leg(pend.lots_leg2, plan.tp2 if self.tcfg.tp2_r > 0 else 0.0, plan.sl))
        pos = Position(plan=plan, lots=round(lots, 8), legs=legs, entry_time=pd.Timestamp(self.idx[minute]),
                       entry_price=fill, risk_money=lots * self.spec.contract_size * plan.risk)
        pos.commission = lots * self.spec.commission_per_lot          # round turn, charged at open
        self.balance -= pos.commission
        self.traded_pois.add(plan.poi_key)
        if plan.grid_leg:
            self.grid_filled += 1
        # netting mode without a separate leg 1: bot closes partial_frac at market when TP1 is touched
        return pos

    # ------------------------------------------------------------------ path helpers
    def _path(self, minute: int, side_ask: bool, buy: Optional[bool] = None) -> List[float]:
        """Intrabar path for one minute in the MT5-tester convention: the extreme AGAINST the
        close is visited first - bullish bar O -> L -> H -> C, bearish bar O -> H -> L -> C.
        ``intrabar="worst"``: the adverse extreme of the position is ALWAYS visited first
        (long: O -> L -> H -> C, short: O -> H -> L -> C) -> stop before target, every bar.
        ``side_ask`` shifts the whole path by the minute's spread (ask side)."""
        o, h, l, c = self.open_[minute], self.high[minute], self.low[minute], self.close[minute]
        sp = self.spread[minute] if side_ask else 0.0
        if self.tcfg.intrabar == "worst" and buy is not None:
            seq = [o, l, h, c] if buy else [o, h, l, c]
        else:
            seq = [o, l, h, c] if c >= o else [o, h, l, c]
        return [x + sp for x in seq]

    def _walk_position(self, pos: Position, minute: int, from_fill: bool = False) -> None:
        """Apply one M1 bar to an open position: SL / TP1 / TP2 / BE logic on the right price side.

        ``from_fill``: the position was filled inside this minute -> only the part of the
        path AFTER the fill point (the bar's extreme on the entry side) is replayed.

        v9 additions (all off by default): target ladder (3+ legs), ``be_trigger_r`` (BE on
        bar-close MFE without a partial), ``ratchet_sl`` (after the k-th partial the stop moves
        to the (k-1)-th target), ``trail_r`` (trailing stop updated from the previous closed
        bar's extreme/close - never inside the current bar, as the live bot only sees closed
        bars), ``max_hold_min`` (time stop at market), ``tp2_r = 0`` (runner without target)."""
        plan = pos.plan
        buy = plan.is_buy
        tc = self.tcfg
        # v13: a plan placed in the range regime may carry its own stop schedule
        sl_after_leg = plan.sl_after_leg or tc.sl_after_leg
        # long: stops/TPs on bid (raw bars); short: on ask (bid + spread)
        path = self._path(minute, side_ask=not buy, buy=buy)
        if from_fill:
            # a buy limit fills at the LOW of the ask path, a sell limit at the HIGH of the bid path;
            # replay from that extreme onwards (the fill price itself is the first point)
            ext = min(path) if buy else max(path)
            k0 = path.index(ext)
            # long: path is bid, fill was on ask -> bid at fill = entry - spread; short: path is ask,
            # fill on bid -> ask at fill = entry + spread.  The bar may have continued to its extreme
            # AFTER the fill (start -> ext) - that part can hit the stop - and then moved on.
            start = pos.entry_price - self.spread[minute] if buy else pos.entry_price + self.spread[minute]
            if worst_mode := (tc.intrabar == "worst"):
                path = [start, ext, path[-1]]          # worst: no favourable extreme after the fill
            else:
                path = [start, ext] + path[k0 + 1:]
        hi = max(path)
        lo = min(path)
        worst = tc.intrabar == "worst"
        t = pd.Timestamp(self.idx[minute])
        sgn = 1.0 if buy else -1.0
        # ---- v9: stop management decided on CLOSED bars (before this bar is walked) ---------------
        if not from_fill and (tc.trail_r > 0 or tc.be_trigger_r > 0 or tc.max_hold_min > 0 or tc.trail_after_leg > 0):
            self._manage_before_bar(pos, minute, t)
            if pos.closed:
                return
        # excursions in R (on the closing side of the position)
        if buy:
            pos.mfe_r = max(pos.mfe_r, (hi - pos.entry_price) / plan.risk)
            pos.mae_r = max(pos.mae_r, (pos.entry_price - lo) / plan.risk)
        else:
            pos.mfe_r = max(pos.mfe_r, (pos.entry_price - lo) / plan.risk)
            pos.mae_r = max(pos.mae_r, (hi - pos.entry_price) / plan.risk)
        be_active = pos.partial_done and minute >= pos.be_at_minute and tc.be_on_partial and not sl_after_leg
        if be_active:
            for l in pos.legs:
                if l.open and self._better_stop(buy, plan.be_price, l.sl):
                    l.sl = plan.be_price
        if pos.sl_queue:                      # v10: delayed stop moves (be_delay_bars with sl_after_leg)
            due = [s for (mm, s) in pos.sl_queue if minute >= mm]
            pos.sl_queue = [(mm, s) for (mm, s) in pos.sl_queue if minute < mm]
            for new_sl in due:
                for l in pos.legs:
                    if l.open and self._better_stop(buy, new_sl, l.sl):
                        l.sl = new_sl
        # walk the path segment by segment
        prev = path[0]
        for k, px in enumerate(path):
            seg_lo, seg_hi = min(prev, px), max(prev, px)
            going_up = px > prev
            prev = px
            for leg in pos.legs:
                if not leg.open:
                    continue
                has_tp = leg.tp > 0
                if buy:
                    hit_sl = seg_lo <= leg.sl
                    hit_tp = has_tp and seg_hi >= leg.tp
                else:
                    hit_sl = seg_hi >= leg.sl
                    hit_tp = has_tp and seg_lo <= leg.tp
                if hit_sl and hit_tp:
                    # both inside one segment: the level closer to the segment start is reached first
                    if worst:
                        first_sl = True
                    elif buy:
                        first_sl = not going_up      # moving down -> SL (below) reached first
                    else:
                        first_sl = going_up          # moving up -> SL (above) reached first
                    if k == 0:                       # open gap: whichever is beyond the open
                        first_sl = (path[0] <= leg.sl) if buy else (path[0] >= leg.sl)
                    hit_tp = not first_sl
                    hit_sl = first_sl
                if hit_sl:
                    price = leg.sl
                    if k == 0 and ((buy and path[0] < leg.sl) or (not buy and path[0] > leg.sl)):
                        price = path[0]              # gapped through the stop
                    price = price - tc.sl_slippage if buy else price + tc.sl_slippage
                    if leg.sl == plan.sl:
                        reason = "sl"
                    elif abs(leg.sl - plan.be_price) < self.spec.point / 2:
                        reason = "be"
                    else:
                        reason = "trail" if sgn * (leg.sl - pos.entry_price) > 0 else "sl"
                    self._close_leg(pos, leg, price, t, reason)
                elif hit_tp:
                    price = leg.tp
                    if k == 0 and ((buy and path[0] > leg.tp) or (not buy and path[0] < leg.tp)):
                        price = path[0]
                    is_last = all((not l2.open) or (l2 is leg) for l2 in pos.legs)
                    is_tp1 = (leg.tp == plan.tp1) and not pos.partial_done and len(pos.legs) > 1
                    self._close_leg(pos, leg, price, t, "tp1" if (is_tp1 or not is_last) else "tp2")
                    if not is_last:
                        pos.n_partials += 1
                        if pos.n_partials == 1 and tc.grid_cancel_on_partial and not plan.grid_leg:
                            self._grid_sync(plan.key, "edge took a partial", minute)   # v14: the deep order is withdrawn
                        if is_tp1 or not pos.partial_done:
                            pos.partial_done = True
                            pos.partial_time = t
                            pos.be_at_minute = minute + self.be_delay
                        if self.be_delay == 0 and tc.be_on_partial and pos.n_partials == 1 and not sl_after_leg:
                            for l2 in pos.legs:
                                if l2.open and self._better_stop(buy, plan.be_price, l2.sl):
                                    l2.sl = plan.be_price
                        if sl_after_leg:
                            # v10: per-leg stop schedule (R from entry) for the remaining legs; "x" = leave the stop
                            # index by the ladder LEVEL that was just hit (robust to merged / empty legs)
                            k = plan.tps.index(leg.tp) if leg.tp in plan.tps else pos.n_partials - 1
                            spec_k = sl_after_leg[k] if k < len(sl_after_leg) else "x"
                            if str(spec_k).lower() not in ("x", "", "none"):
                                new_sl = self.spec.round_price(pos.entry_price + sgn * float(spec_k) * plan.risk) \
                                    if abs(float(spec_k)) > 1e-12 else plan.be_price
                                if self.be_delay == 0:
                                    for l2 in pos.legs:
                                        if l2.open and self._better_stop(buy, new_sl, l2.sl):
                                            l2.sl = new_sl
                                else:
                                    pos.sl_queue.append((minute + self.be_delay, new_sl))
                        if tc.ratchet_sl and pos.n_partials >= 2:
                            # stop of the rest -> previous target (the one closed before this one)
                            # closed targets sorted from entry outwards; the second-farthest is the previous one
                            prev_tp = sorted((l2.tp for l2 in pos.legs if not l2.open and l2.tp > 0), reverse=not buy)
                            if len(prev_tp) >= 2:
                                new_sl = prev_tp[-2]
                                for l2 in pos.legs:
                                    if l2.open and self._better_stop(buy, new_sl, l2.sl):
                                        l2.sl = new_sl
                        # the remaining legs only see the part of the segment AFTER the partial
                        seg_lo, seg_hi = min(price, px), max(price, px)
            # netting mode: single leg, bot closes partial_frac at market when TP1 is touched
            if len(pos.legs) == 1 and not pos.partial_done and tc.exec_mode == "netting" and pos.legs[0].open \
                    and plan.partial_frac > 0:
                leg = pos.legs[0]
                touched = (seg_hi >= plan.tp1) if buy else (seg_lo <= plan.tp1)
                if touched:
                    part = self.spec.round_volume_down(leg.lots * plan.partial_frac)
                    if part >= self.spec.volume_min and (leg.lots - part) >= self.spec.volume_min - 1e-9:
                        px_close = plan.tp1 - tc.market_slippage if buy else plan.tp1 + tc.market_slippage
                        new_leg = Leg(part, plan.tp1, leg.sl, open=False, close_price=px_close, close_time=t, close_reason="tp1")
                        new_leg.pnl = sgn * (px_close - pos.entry_price) * part * self.spec.contract_size
                        self.balance += new_leg.pnl
                        leg.lots = round(leg.lots - part, 8)
                        pos.legs.insert(0, new_leg)
                    pos.partial_done = True
                    pos.partial_time = t
                    pos.n_partials += 1
                    pos.be_at_minute = minute + self.be_delay
                    if self.be_delay == 0 and tc.be_on_partial:
                        leg.sl = plan.be_price
                        # rest of this segment (after TP1) can already hit the BE stop
                        rest_lo, rest_hi = min(plan.tp1, px), max(plan.tp1, px)
                        if (buy and rest_lo <= leg.sl) or (not buy and rest_hi >= leg.sl):
                            price = leg.sl - tc.sl_slippage if buy else leg.sl + tc.sl_slippage
                            self._close_leg(pos, leg, price, t, "be")
            if all(not l.open for l in pos.legs):
                break
        # ---- v9: update the trailing high-water mark with this (now closed) bar
        if tc.trail_r > 0 and not pos.closed:
            ref = (hi if tc.trail_source == "extreme" else path[-1]) if buy else (lo if tc.trail_source == "extreme" else path[-1])
            if math.isnan(pos.hwm) or sgn * (ref - pos.hwm) > 0:
                pos.hwm = ref
        if all(not l.open for l in pos.legs):
            self._finish(pos, t)

    @staticmethod
    def _better_stop(buy: bool, new_sl: float, cur_sl: float) -> bool:
        """True when ``new_sl`` is tighter (closer to / beyond price in the favourable direction)."""
        return new_sl > cur_sl if buy else new_sl < cur_sl

    def _manage_before_bar(self, pos: Position, minute: int, t: pd.Timestamp) -> None:
        """v9 stop management evaluated at the OPEN of bar ``minute`` from the bars already closed
        (exactly what the live bot can do once per closed M1 bar): time stop, BE trigger, trailing."""
        plan, tc = pos.plan, self.tcfg
        buy = plan.is_buy
        sgn = 1.0 if buy else -1.0
        # time stop: close the remaining legs at market at this bar's open
        if tc.max_hold_min > 0 and (t - pos.entry_time).total_seconds() / 60.0 >= tc.max_hold_min:
            bid = self.open_[minute]
            ask = bid + self.spread[minute]
            px = (bid - tc.market_slippage) if buy else (ask + tc.market_slippage)
            for leg in pos.legs:
                if leg.open:
                    self._close_leg(pos, leg, px, t, "time")
            self._finish(pos, t)
            return
        # BE trigger on bar-close MFE (independent of partials)
        if tc.be_trigger_r > 0 and not pos.be_armed:
            # pos.mfe_r = MFE of the bars closed so far (this bar has not been walked yet)
            if pos.mfe_r >= tc.be_trigger_r:
                pos.be_armed = True
                for leg in pos.legs:
                    if leg.open and self._better_stop(buy, plan.be_price, leg.sl):
                        leg.sl = plan.be_price
        # trailing stop from the high-water mark of the closed bars
        if tc.trail_r > 0 and not math.isnan(pos.hwm):
            if tc.trail_after_leg > 0:
                if pos.n_partials < tc.trail_after_leg:
                    return
            elif tc.trail_after_partial and not pos.partial_done and len(pos.legs) > 1:
                return
            hwm_r = sgn * (pos.hwm - pos.entry_price) / plan.risk
            if hwm_r < tc.trail_start_r:
                return
            new_sl = self.spec.round_price(pos.hwm - sgn * tc.trail_r * plan.risk)
            for leg in pos.legs:
                if leg.open and self._better_stop(buy, new_sl, leg.sl):
                    leg.sl = new_sl

    def _close_leg(self, pos: Position, leg: Leg, price: float, t: pd.Timestamp, reason: str) -> None:
        sgn = 1.0 if pos.plan.is_buy else -1.0
        leg.open = False
        leg.close_price = self.spec.round_price(price)
        leg.close_time = t
        leg.close_reason = reason
        leg.pnl = sgn * (leg.close_price - pos.entry_price) * leg.lots * self.spec.contract_size
        self.balance += leg.pnl

    def _finish(self, pos: Position, t: pd.Timestamp) -> None:
        pos.closed = True
        pos.close_time = t
        reasons = [l.close_reason for l in pos.legs]
        if "tp2" in reasons:
            pos.outcome = "tp2"
        elif "forced" in reasons:
            pos.outcome = "forced"
        elif "stopout" in reasons:
            pos.outcome = "stopout"
        elif "halt" in reasons:
            pos.outcome = "halt"             # v10: total-loss limit
        elif "daily_halt" in reasons:
            pos.outcome = "daily_halt"       # v10: daily-loss limit
        elif "trail" in reasons:
            pos.outcome = "trail"            # v9: runner stopped by the trailing / ratchet stop in profit
        elif "time" in reasons:
            pos.outcome = "time"             # v9: time stop
        elif "tp1" in reasons and "be" in reasons:
            pos.outcome = "partial_be"
        elif "tp1" in reasons and "sl" in reasons:
            pos.outcome = "partial_sl"       # be_delay: stopped at the ORIGINAL stop after the partial
        elif "be" in reasons:
            pos.outcome = "be"               # v9: BE trigger without a partial
        else:
            pos.outcome = "sl"
        self.positions.pop(pos.plan.key, None)
        self.closed.append(pos)
        # v14: the streak state sees every closed EDGE plan (deep grid legs share the edge's outcome and are not counted twice)
        if self.mart.on and not pos.plan.grid_leg:
            net = sum(l.pnl for l in pos.legs) - pos.commission + pos.swap
            self.mart.on_close(pos.plan.tf, net, net / pos.risk_money if pos.risk_money > 0 else 0.0, pos.plan.mart_step)
        if not pos.plan.grid_leg:
            self._grid_sync(pos.plan.key, "edge closed", self.cur_minute)
        # v12: re-arm the zone after a break-even exit
        if self.tcfg.reentry_bars > 0 and pos.outcome in self.tcfg.reentry_outcomes and not pos.plan.grid_leg:
            self._rearm(pos, self.cur_minute)

    def _force_close_all(self, minute: int, reason: str) -> None:
        t = pd.Timestamp(self.idx[minute])
        bid = self.close[minute]
        ask = bid + self.spread[minute]
        for pos in list(self.positions.values()):
            for leg in pos.legs:
                if leg.open:
                    px = (bid - self.tcfg.market_slippage) if pos.plan.is_buy else (ask + self.tcfg.market_slippage)
                    self._close_leg(pos, leg, px, t, reason)
            self._finish(pos, t)
        for k in list(self.pending):
            self._cancel(k, reason, minute)

    # ------------------------------------------------------------------ main loop
    def run(self, progress: bool = False) -> "SimResult":
        ev_i = 0
        n_ev = len(self.sel)
        last_day = None
        sample_every = 60
        for m in range(self.n):
            if self.stopped_out or self.halted:
                break
            self.cur_minute = m
            t64 = self.idx[m]
            # 1) act on selection events stamped at/before this bar's open
            while ev_i < n_ev and self.sel_minute[ev_i] <= m:
                self._on_event(self.sel.iloc[ev_i], m)
                ev_i += 1
            # 2) expire pending (persist policy) / v11 grace period elapsed
            for k, p in list(self.pending.items()):
                if m >= p.expires_minute:
                    self._cancel(k, "expired", m)
                elif p.grace_until >= 0 and m >= p.grace_until:
                    self._cancel(k, p.grace_reason + " (grace)", m)
            # 3) fills (a pending order filled this minute is also exposed to the rest of this minute's path)
            for k, p in list(self.pending.items()):
                if k not in self.pending:          # v14: cancelled by an earlier fill of this minute (grid sync)
                    continue
                pos = self._try_fill(p, m)
                if pos is not None:
                    self.pending.pop(k, None)
                    self.positions[k] = pos
                    # after a fill the remaining path of the minute can hit SL/TP
                    self._walk_position(pos, m, from_fill=True)
                    if pos.closed:
                        continue
            # 4) walk open positions (those filled this minute were already walked)
            for pos in list(self.positions.values()):
                if pos.entry_time != pd.Timestamp(t64):
                    self._walk_position(pos, m)
            # 5) swaps at the daily rollover (server midnight) and equity
            day = t64.astype("datetime64[D]")
            if last_day is not None and day != last_day and self.positions:
                wd = pd.Timestamp(day).weekday()
                mult = 3.0 if wd == self.spec.swap_triple_weekday else 1.0
                for pos in self.positions.values():
                    per = self.spec.swap_long_per_lot if pos.plan.is_buy else self.spec.swap_short_per_lot
                    s = per * pos.open_lots * mult
                    pos.swap += s
                    self.balance += s
            if last_day is not None and day != last_day:
                self.day_start_balance = self.balance + self._floating(self.close[m], self.close[m] + self.spread[m])
                self.daily_halt_day = None                  # a new server day: trading allowed again
            last_day = day
            # optional weekend flatten
            if self.tcfg.friday_close_hour_server is not None:
                ts = pd.Timestamp(t64)
                if ts.weekday() == 4 and ts.hour >= self.tcfg.friday_close_hour_server and (self.positions or self.pending):
                    self._force_close_all(m, "forced")
            bid = self.close[m]
            ask = bid + self.spread[m]
            self.equity = self.balance + self._floating(bid, ask)
            # v10 account protection: total limit (halt for good) then daily limit (flat until the next server day)
            if self.tcfg.max_total_loss_pct > 0 and not self.halted and \
                    self.equity <= self.tcfg.balance * (1.0 - self.tcfg.max_total_loss_pct / 100.0):
                self._force_close_all(m, "halt")
                self.halted = True
                self.halt_time = pd.Timestamp(t64)
                self.equity = self.balance
            elif self.tcfg.max_daily_loss_pct > 0 and self.daily_halt_day is None and \
                    self.equity <= self.day_start_balance * (1.0 - self.tcfg.max_daily_loss_pct / 100.0):
                self._force_close_all(m, "daily_halt")
                self.daily_halt_day = day
                self.daily_halts.append((pd.Timestamp(t64), self.equity))
                self.equity = self.balance
            used = self._margin_used(bid)
            if used > 0 and self.equity / used < self.tcfg.stop_out_level:
                self._force_close_all(m, "stopout")
                self.stopped_out = True
                self.equity = self.balance
            if m % sample_every == 0 or m == self.n - 1:
                self.equity_curve.append((t64, self.balance, self.equity))
            if progress and m % 50000 == 0:
                print(f"  {pd.Timestamp(t64)}  bal {self.balance:.0f} eq {self.equity:.0f} open {len(self.positions)} "
                      f"pend {len(self.pending)} closed {len(self.closed)}", flush=True)
        # end of data: mark open positions to market (they stay open live; we close them for the statistics)
        if self.positions:
            self._force_close_all(self.n - 1, "forced")
        return SimResult(self)


# ---------------------------------------------------------------------------- result
class SimResult:
    def __init__(self, sim: PortfolioSimulator):
        self.sim = sim
        self.tcfg = sim.tcfg
        self.trades = self._trades_frame()
        self.equity = pd.DataFrame(sim.equity_curve, columns=["time", "balance", "equity"]).set_index("time")

    def _trades_frame(self) -> pd.DataFrame:
        rows = []
        cs = self.sim.spec.contract_size
        for p in self.sim.closed:
            gross = sum(l.pnl for l in p.legs)
            net = gross - p.commission + p.swap
            rows.append({
                "key": p.plan.key, "tf": p.plan.tf, "poi_id": p.plan.poi_id, "kind": p.plan.kind, "side": p.plan.side,
                "quality": p.plan.quality, "grade": p.plan.grade, "selected_time": p.plan.selected_time,
                "entry_time": p.entry_time, "close_time": p.close_time,
                "hold_min": (p.close_time - p.entry_time).total_seconds() / 60.0 if p.close_time is not None else np.nan,
                "entry": p.entry_price, "limit": p.plan.entry, "sl": p.plan.sl, "tp1": p.plan.tp1, "tp2": p.plan.tp2,
                "zone_top": p.plan.zone_top, "zone_bottom": p.plan.zone_bottom, "risk_usd_per_unit": p.plan.risk,
                "atr": p.plan.atr, "lots": p.lots, "risk_money": p.risk_money,
                "gross": gross, "commission": p.commission, "swap": p.swap, "net": net,
                "r_gross": gross / p.risk_money if p.risk_money > 0 else np.nan,
                "r_net": net / p.risk_money if p.risk_money > 0 else np.nan,
                "outcome": p.outcome, "partial": p.partial_done, "mfe_r": p.mfe_r, "mae_r": p.mae_r,
                "reentry": p.plan.reentry_n, "confluent": bool(getattr(p.plan, "confluent", False)),
                "regime": getattr(p.plan, "regime", ""),
                "mart_step": p.plan.mart_step, "mart_scale": round(p.plan.mart_scale, 4),
                "grid_leg": bool(p.plan.grid_leg), "grid_parent": p.plan.grid_parent,
                "legs": ";".join(f"{l.lots}@{l.close_price:.2f}:{l.close_reason}" for l in p.legs),
            })
        df = pd.DataFrame(rows)
        if len(df):
            df = df.sort_values("close_time").reset_index(drop=True)
            df["cum_net"] = df.net.cumsum()
            df["cum_r"] = df.r_net.cumsum()
        return df

    # ------------------------------------------------------------------ stats
    def summary(self) -> Dict[str, float]:
        t = self.trades
        s = self.sim
        out: Dict[str, float] = {"start_balance": self.tcfg.balance, "end_balance": round(s.balance, 2),
                                 "trades": len(t), "pending_placed": len(t) + len(s.cancelled),
                                 "cancelled": len(s.cancelled), "skipped": len(s.skipped),
                                 "reentries_placed": s.reentries_placed,
                                 "reentry_trades": int((t.reentry > 0).sum()) if len(t) else 0,
                                 "confluent_trades": int(t.confluent.sum()) if len(t) else 0,
                                 "range_trades": int((t.regime == "range").sum()) if len(t) else 0,
                                 "range_plans": s.regime_counts.get("range", 0),
                                 "mart_trades": int((t.mart_step > 0).sum()) if len(t) else 0,
                                 "mart_down_trades": int((t.mart_step < 0).sum()) if len(t) else 0,
                                 "mart_max_scale": round(float(t.mart_scale.max()), 3) if len(t) else 1.0,
                                 "grid_placed": s.grid_placed, "grid_filled": s.grid_filled,
                                 "grid_leg_trades": int(t.grid_leg.sum()) if len(t) else 0,
                                 "edge_trades": int((~t.grid_leg).sum()) if len(t) else 0}
        if not len(t):
            return out
        r = t.r_net
        eq = self.equity.equity
        peak = eq.cummax()
        dd = (eq - peak)
        dd_pct = (eq / peak - 1.0)
        days = max((t.close_time.max() - t.entry_time.min()).total_seconds() / 86400.0, 1.0)
        wins = t[t.net > 0]
        losses = t[t.net < 0]
        cum_r = r.cumsum()
        dd_r = (cum_r - cum_r.cummax()).min()
        out.update({
            "net_profit": round(t.net.sum(), 2),
            "return_%": round(100 * (s.balance / self.tcfg.balance - 1), 2),
            "total_R": round(r.sum(), 2),
            "avg_R": round(r.mean(), 4),
            "median_R": round(r.median(), 4),
            "win_%": round(100 * (t.net > 0).mean(), 1),
            "profit_factor": round(wins.net.sum() / abs(losses.net.sum()), 3) if len(losses) and losses.net.sum() != 0 else float("inf"),
            "avg_win_R": round(wins.r_net.mean(), 3) if len(wins) else 0.0,
            "avg_loss_R": round(losses.r_net.mean(), 3) if len(losses) else 0.0,
            "max_dd_$": round(dd.min(), 2),
            "max_dd_%": round(100 * dd_pct.min(), 2),
            "max_dd_R": round(dd_r, 2),
            "trades_per_day": round(len(t) / days, 2),
            "days": round(days, 1),
            "sharpe_daily": self._sharpe(),
            "partial_hit_%": round(100 * t.partial.mean(), 1),
            "tp2_%": round(100 * (t.outcome == "tp2").mean(), 1),
            "partial_be_%": round(100 * (t.outcome == "partial_be").mean(), 1),
            "sl_%": round(100 * (t.outcome == "sl").mean(), 1),
            "forced_%": round(100 * (t.outcome.isin(["forced", "stopout"])).mean(), 1),
            "daily_halts": len(s.daily_halts),
            "halted": bool(s.halted),
            "halt_time": str(s.halt_time) if s.halt_time is not None else "",
            "commission_$": round(t.commission.sum(), 2),
            "swap_$": round(t.swap.sum(), 2),
            "avg_hold_min": round(t.hold_min.mean(), 0),
            "median_hold_min": round(t.hold_min.median(), 0),
            "avg_lots": round(t.lots.mean(), 3),
            "avg_risk_$": round(t.risk_money.mean(), 2),
            "expectancy_$": round(t.net.mean(), 2),
            "stopped_out": bool(s.stopped_out),
        })
        return out

    def _sharpe(self) -> float:
        if not len(self.trades):
            return 0.0
        daily = self.trades.set_index("close_time").net.resample("1D").sum()
        daily = daily[daily.index.dayofweek < 5]
        if daily.std() == 0 or len(daily) < 5:
            return 0.0
        return round(float(daily.mean() / daily.std() * math.sqrt(252)), 2)

    def by(self, col: str, t: Optional[pd.DataFrame] = None) -> pd.DataFrame:
        t = self.trades if t is None else t
        if not len(t):
            return pd.DataFrame()
        g = t.groupby(col)
        out = pd.DataFrame({
            "trades": g.size(), "win_%": (100 * g.apply(lambda x: (x.net > 0).mean())).round(1),
            "avg_R": g.r_net.mean().round(4), "total_R": g.r_net.sum().round(2), "net_$": g.net.sum().round(2),
            "tp2_%": (100 * g.apply(lambda x: (x.outcome == "tp2").mean())).round(1),
            "partial_%": (100 * g.partial.mean()).round(1),
            "PF": g.apply(lambda x: x[x.net > 0].net.sum() / abs(x[x.net < 0].net.sum()) if (x.net < 0).any() else float("inf")).round(2),
        })
        return out

    def monthly(self) -> pd.DataFrame:
        t = self.trades
        if not len(t):
            return pd.DataFrame()
        t = t.assign(month=t.close_time.dt.strftime("%Y-%m"))
        return self.by("month", t)

    def skipped_reasons(self) -> pd.Series:
        return pd.Series([r for _, r in self.sim.skipped]).value_counts() if self.sim.skipped else pd.Series(dtype=int)

    def cancel_reasons(self) -> pd.Series:
        return pd.Series([c.reason_cancel for c in self.sim.cancelled]).value_counts() if self.sim.cancelled else pd.Series(dtype=int)

    def filter_reasons(self) -> pd.Series:
        return pd.Series([r for _, r in self.sim.filtered]).value_counts() if self.sim.filtered else pd.Series(dtype=int)



# ==============================================================================
# MT5 BROKER ADAPTER   (inlined from lubot/mt5_broker.py)
# ==============================================================================
# Broker adapter around the ``MetaTrader5`` Python package.
#
# Attach-only: ``mt5.initialize()`` with NO login/password/server.  The package
# connects to the MT5 terminal that is already running on this Windows machine and
# uses the account the terminal is logged in to.  If no terminal is running it starts
# the last-used one (``path`` may point to a specific ``terminal64.exe``).
#
# Everything the live trader needs is wrapped here so that ``trader.py`` can be tested
# against :class:`FakeMT5` (``tests/fake_mt5.py``) without a terminal.

try:  # pragma: no cover
    import MetaTrader5 as _mt5  # type: ignore
except Exception:  # noqa: BLE001
    _mt5 = None


@dataclass
class BrokerOrder:
    ticket: int
    kind: str            # "buy_limit" | "sell_limit"
    price: float
    sl: float
    tp: float
    volume: float
    magic: int
    comment: str
    time_setup: Optional[pd.Timestamp] = None


@dataclass
class BrokerPosition:
    ticket: int
    side: str            # buy / sell
    price_open: float
    sl: float
    tp: float
    volume: float
    magic: int
    comment: str
    profit: float = 0.0
    time: Optional[pd.Timestamp] = None


class MT5Broker:
    def __init__(self, symbol: str, mt5=None, path: Optional[str] = None, deviation_points: int = 30,
                 timeout_ms: int = 60_000):
        self.mt5 = mt5 or _mt5
        if self.mt5 is None:
            raise RuntimeError("MetaTrader5 package not available - run on Windows with `pip install MetaTrader5` "
                               "and the MT5 terminal open and logged in.")
        self.symbol = symbol
        self.deviation = deviation_points
        kwargs = {"timeout": timeout_ms}
        if path:
            kwargs["path"] = path
        # NO login / password / server: attach to the running, already logged-in terminal
        if not self.mt5.initialize(**kwargs):
            raise RuntimeError(f"mt5.initialize() failed: {self.mt5.last_error()} - is the MT5 terminal open and logged in?")
        if not self.mt5.symbol_select(symbol, True):
            raise RuntimeError(f"symbol_select({symbol}) failed: {self.mt5.last_error()}")
        info = self.mt5.symbol_info(symbol)
        if info is None:
            raise RuntimeError(f"symbol {symbol} not found in Market Watch")
        self.info = info
        acc = self.mt5.account_info()
        if acc is None:
            raise RuntimeError("account_info() is None - terminal not logged in?")
        self.account = acc
        self.hedging = getattr(acc, "margin_mode", 2) == getattr(self.mt5, "ACCOUNT_MARGIN_MODE_RETAIL_HEDGING", 2)
        self.filling = self._pick_filling(info)

    # ------------------------------------------------------------------ info
    def _pick_filling(self, info) -> int:
        m = self.mt5
        modes = getattr(info, "filling_mode", 0)
        if modes & getattr(m, "SYMBOL_FILLING_FOK", 1):
            return m.ORDER_FILLING_FOK
        if modes & getattr(m, "SYMBOL_FILLING_IOC", 2):
            return m.ORDER_FILLING_IOC
        return getattr(m, "ORDER_FILLING_RETURN", 2)

    def spec(self, commission_per_lot: float = 0.0) -> SymbolSpec:
        i = self.info
        return SymbolSpec(symbol=self.symbol, digits=i.digits, point=i.point, contract_size=i.trade_contract_size,
                          volume_min=i.volume_min, volume_max=i.volume_max, volume_step=i.volume_step,
                          stops_level_points=getattr(i, "trade_stops_level", 0), commission_per_lot=commission_per_lot,
                          swap_long_per_lot=getattr(i, "swap_long", 0.0), swap_short_per_lot=getattr(i, "swap_short", 0.0),
                          leverage=float(getattr(self.account, "leverage", 100)), currency=self.account.currency)

    def refresh_account(self):
        acc = self.mt5.account_info()
        if acc is not None:
            self.account = acc
        return self.account

    @property
    def equity(self) -> float:
        return float(self.refresh_account().equity)

    @property
    def balance(self) -> float:
        return float(self.account.balance)

    def tick(self):
        return self.mt5.symbol_info_tick(self.symbol)

    def price(self) -> Dict[str, float]:
        t = self.tick()
        return {"bid": float(t.bid), "ask": float(t.ask), "time": float(t.time)}

    def server_utc_offset_hours(self) -> float:
        t = self.tick()
        if t is None:
            return 0.0
        server_now = datetime.fromtimestamp(t.time, tz=timezone.utc)
        diff_h = (server_now - datetime.now(timezone.utc)).total_seconds() / 3600.0
        return round(diff_h * 2) / 2.0

    # ------------------------------------------------------------------ history
    def m1_history(self, bars: int) -> pd.DataFrame:
        rates = self.mt5.copy_rates_from_pos(self.symbol, self.mt5.TIMEFRAME_M1, 0, bars)
        if rates is None or len(rates) == 0:
            raise RuntimeError(f"copy_rates_from_pos failed: {self.mt5.last_error()}")
        df = frame_from_mt5_rates(rates)
        try:
            sp = pd.Series(rates["spread"], index=df.index).astype(float) * self.info.point
            df["spread"] = sp
        except Exception:  # noqa: BLE001
            pass
        return df

    def m1_since(self, since: pd.Timestamp) -> pd.DataFrame:
        start = since.to_pydatetime().replace(tzinfo=timezone.utc)
        rates = self.mt5.copy_rates_range(self.symbol, self.mt5.TIMEFRAME_M1, start,
                                          datetime.now(timezone.utc) + timedelta(days=2))
        if rates is None or len(rates) == 0:
            return pd.DataFrame()
        df = frame_from_mt5_rates(rates)
        try:
            df["spread"] = pd.Series(rates["spread"], index=df.index).astype(float) * self.info.point
        except Exception:  # noqa: BLE001
            pass
        return df

    # ------------------------------------------------------------------ state
    def orders(self, magic: Optional[int] = None) -> List[BrokerOrder]:
        raw = self.mt5.orders_get(symbol=self.symbol) or []
        out = []
        for o in raw:
            if magic is not None and o.magic != magic:
                continue
            kind = "buy_limit" if o.type == self.mt5.ORDER_TYPE_BUY_LIMIT else \
                   "sell_limit" if o.type == self.mt5.ORDER_TYPE_SELL_LIMIT else str(o.type)
            out.append(BrokerOrder(o.ticket, kind, float(o.price_open), float(o.sl), float(o.tp),
                                   float(o.volume_current), int(o.magic), str(o.comment),
                                   pd.Timestamp(o.time_setup, unit="s")))
        return out

    def positions(self, magic: Optional[int] = None) -> List[BrokerPosition]:
        raw = self.mt5.positions_get(symbol=self.symbol) or []
        out = []
        for p in raw:
            if magic is not None and p.magic != magic:
                continue
            side = BUY if p.type == self.mt5.POSITION_TYPE_BUY else SELL
            out.append(BrokerPosition(p.ticket, side, float(p.price_open), float(p.sl), float(p.tp), float(p.volume),
                                      int(p.magic), str(p.comment), float(p.profit), pd.Timestamp(p.time, unit="s")))
        return out

    def position_pnl(self, ticket: int) -> Optional[float]:
        """v14: realised net P&L (profit + commission + swap) of a CLOSED position from the deal history; None if unknown."""
        try:
            deals = self.mt5.history_deals_get(position=ticket) or []
        except Exception:  # noqa: BLE001
            return None
        if not deals:
            return None
        return float(sum(float(getattr(d, "profit", 0.0)) + float(getattr(d, "commission", 0.0)) + float(getattr(d, "swap", 0.0))
                         for d in deals))

    # ------------------------------------------------------------------ actions
    def _send(self, request: dict, what: str) -> Optional[object]:
        for attempt in range(3):
            res = self.mt5.order_send(request)
            if res is None:
                err = self.mt5.last_error()
                print(f"[broker] {what}: order_send returned None {err}")
                time.sleep(0.5)
                continue
            if res.retcode in (self.mt5.TRADE_RETCODE_DONE, getattr(self.mt5, "TRADE_RETCODE_PLACED", 10008),
                               getattr(self.mt5, "TRADE_RETCODE_DONE_PARTIAL", 10010)):
                return res
            if res.retcode in (getattr(self.mt5, "TRADE_RETCODE_REQUOTE", 10004),
                               getattr(self.mt5, "TRADE_RETCODE_PRICE_CHANGED", 10020),
                               getattr(self.mt5, "TRADE_RETCODE_PRICE_OFF", 10021)):
                time.sleep(0.3)
                continue
            if res.retcode == getattr(self.mt5, "TRADE_RETCODE_INVALID_FILL", 10030) and "type_filling" in request:
                request = dict(request, type_filling=self.mt5.ORDER_FILLING_IOC if request["type_filling"] != self.mt5.ORDER_FILLING_IOC
                               else getattr(self.mt5, "ORDER_FILLING_RETURN", 2))
                continue
            print(f"[broker] {what} failed: retcode={res.retcode} {getattr(res, 'comment', '')}")
            return None
        return None

    def place_limit(self, side: str, volume: float, price: float, sl: float, tp: float, magic: int,
                    comment: str) -> Optional[int]:
        m = self.mt5
        req = {
            "action": m.TRADE_ACTION_PENDING, "symbol": self.symbol, "volume": float(volume),
            "type": m.ORDER_TYPE_BUY_LIMIT if side == BUY else m.ORDER_TYPE_SELL_LIMIT,
            "price": float(price), "sl": float(sl), "tp": float(tp), "deviation": self.deviation,
            "magic": int(magic), "comment": comment[:31], "type_time": m.ORDER_TIME_GTC,
            "type_filling": getattr(m, "ORDER_FILLING_RETURN", 2),
        }
        res = self._send(req, f"place {side} limit {volume}@{price}")
        return int(res.order) if res is not None else None

    def cancel_order(self, ticket: int) -> bool:
        req = {"action": self.mt5.TRADE_ACTION_REMOVE, "order": int(ticket)}
        return self._send(req, f"cancel #{ticket}") is not None

    def modify_position(self, ticket: int, sl: float, tp: float) -> bool:
        req = {"action": self.mt5.TRADE_ACTION_SLTP, "symbol": self.symbol, "position": int(ticket),
               "sl": float(sl), "tp": float(tp)}
        return self._send(req, f"modify #{ticket} sl={sl} tp={tp}") is not None

    def close_position(self, pos: BrokerPosition, volume: Optional[float] = None, comment: str = "close") -> bool:
        m = self.mt5
        t = self.tick()
        vol = float(volume if volume is not None else pos.volume)
        req = {
            "action": m.TRADE_ACTION_DEAL, "symbol": self.symbol, "volume": vol, "position": int(pos.ticket),
            "type": m.ORDER_TYPE_SELL if pos.side == BUY else m.ORDER_TYPE_BUY,
            "price": float(t.bid if pos.side == BUY else t.ask), "deviation": self.deviation,
            "magic": int(pos.magic), "comment": comment[:31], "type_time": m.ORDER_TIME_GTC, "type_filling": self.filling,
        }
        return self._send(req, f"close #{pos.ticket} {vol}") is not None

    def shutdown(self) -> None:
        try:
            self.mt5.shutdown()
        except Exception:  # noqa: BLE001
            pass


def wait_for_next_minute(offset_seconds: float = 2.0) -> None:
    now = time.time()
    nxt = (int(now // 60) + 1) * 60 + offset_seconds
    time.sleep(max(0.0, nxt - now))



# ==============================================================================
# BOT HELPERS (scan printing / config overrides)   (inlined from bot.py (selected functions))
# ==============================================================================

def apply_overrides(cfg: StrategyConfig, overrides: Optional[str]) -> StrategyConfig:
    """--set key=value,key=value"""
    if not overrides:
        return cfg
    valid = {f.name: f.type for f in fields(cfg)}
    for pair in overrides.split(","):
        k, v = pair.split("=", 1)
        k = k.strip()
        if k not in valid:
            raise SystemExit(f"unknown config key {k}")
        cur = getattr(cfg, k)
        if isinstance(cur, bool):
            val = v.strip().lower() in ("1", "true", "yes")
        elif isinstance(cur, int):
            val = int(v)
        elif isinstance(cur, float):
            val = float(v)
        elif isinstance(cur, tuple):
            val = tuple(x.strip() for x in v.split("|"))
        else:
            val = v
        setattr(cfg, k, val)
    return cfg


def fmt_poi(d: Optional[Dict]) -> str:
    if not d:
        return "none - waiting"
    liq = ", ".join(d["liquidity_between"][:4])
    ctx = d.get("context", {})
    of = f"OF near {int(ctx.get('of_near', 0))}/recent {int(ctx.get('of_recent', 0))}" if ctx else f"OF x{d['orderflow_count']}"
    q = f"  P(bounce>=1ATR)={d['quality']:.0%}" if d.get("quality") is not None else ""
    grade = f" [{d['grade']}]" if d.get("grade") else ""
    if d.get("stage") == "approach":
        grade += " (approach)"
    htf = ""
    if ctx.get("htf_confluence"):
        htf = "  HTF-confluence"
    elif ctx.get("htf_bias_aligned", 0) > 0:
        htf = "  HTF-aligned"
    behind = f"  liq-behind {int(ctx['liq_behind_n'])}" if ctx.get("liq_behind_n") else ""
    return (f"{d['type']:<3} {d['direction']:<7} zone {d['bottom']:.2f} - {d['top']:.2f}  "
            f"(mid {d['mid']:.2f}, key {d['key_level']})  dist {d['distance']:.2f} ({d['distance_atr']} ATR){q}{grade}  "
            f"{of}{htf}{behind}  liq->[{liq}]  {d['time']}")


def fmt_indicators(d: Optional[Dict]) -> str:
    """v5 - one-line indicator picture of the zone (all values oriented to the zone's
    direction: '+' favours a bounce from it)."""
    ctx = (d or {}).get("context", {})
    if not ctx or "ind_rsi_aligned" not in ctx:
        return ""
    bull = d["direction"] == "bullish"
    rsi = 50.0 - ctx["ind_rsi_aligned"] if bull else 50.0 + ctx["ind_rsi_aligned"]
    parts = [f"RSI {rsi:.0f}" + (" div" if ctx.get("ind_rsi_div_regular") else ""),
             f"ADX {ctx['ind_adx']:.0f}" + (" trend-with" if ctx["ind_di_aligned"] > 5 else " trend-against" if ctx["ind_di_aligned"] < -5 else ""),
             "zone beyond BB" if ctx.get("ind_zone_beyond_bb") else "zone inside BB",
             "BB squeeze" if ctx.get("ind_bb_squeeze") else None,
             f"MA-conf x{int(ctx['ind_zone_at_ma'])}" if ctx.get("ind_zone_at_ma") else None,
             "VWAP band" if ctx.get("ind_zone_at_vwap_band") else None,
             "pivot" if ctx.get("ind_zone_at_pivot") else None,
             "OTE" if ctx.get("ind_zone_in_ote") else None,
             "ST aligned" if ctx.get("ind_supertrend_aligned", 0) > 0 else "ST against",
             f"HTF RSI {50 - ctx['htf_rsi_aligned'] if bull else 50 + ctx['htf_rsi_aligned']:.0f}" if "htf_rsi_aligned" in ctx else None,
             f"relvol {ctx['ind_relvol']:.1f}" if ctx.get("ind_relvol", 1.0) != 1.0 else None,
             f"ATR pct {ctx['ind_atr_pctile']:.0%}"]
    return "  |  ".join(p for p in parts if p)


def fmt_levels(d: Optional[Dict]) -> str:
    """v6 - one-line *level memory* picture of the zone: how the market treated this price
    area before (reversals in the zone direction vs. slices through it, visits, value area,
    volume node)."""
    ctx = (d or {}).get("context", {})
    if not ctx or "lv_rev_with" not in ctx:
        return ""
    rw, ra = int(ctx["lv_rev_with"]), int(ctx["lv_rev_against"])
    dens = ctx.get("lv_vol_density", 1.0)
    node = "LVN" if dens < 0.6 else "HVN" if dens > 1.4 else "mid-volume"
    parts = [f"reversals here {rw} with / {ra} against",
             f"rev/visit {ctx['lv_rev_per_visit']:.2f}",
             f"sliced {ctx['lv_slice_frac']:.0%} of visits",
             f"last visit {int(ctx['lv_bars_since_visit'])} bars ago",
             f"{node} (x{dens:.1f})",
             "outside value area" if ctx.get("lv_zone_outside_va") else ("at VA edge" if ctx.get("lv_zone_at_va_edge") else "inside value area"),
             "POC beyond zone" if ctx.get("lv_poc_beyond") else None,
             f"HTF reversals {int(ctx['hlv_rev_with'])}" if "hlv_rev_with" in ctx else None]
    return "  |  ".join(p for p in parts if p)


def print_scan(result: Dict[str, Dict]) -> None:
    for tf, r in result.items():
        print(f"\n=== {tf} | {r['time']} | price {r['price']:.2f} | range {r['range_bias']} ({r['price_zone']}) "
              f"| candidates above {r['candidates_above']} / below {r['candidates_below']}")
        print(f"  ABOVE: {fmt_poi(r['above'])}")
        print(f"  BELOW: {fmt_poi(r['below'])}")
        for side in ("above", "below"):
            d = r[side]
            if d and d.get("why"):
                print(f"         {side} drivers: " + ", ".join(f"{k} {v:+.2f}" for k, v in d["why"]))
            ind = fmt_indicators(d)
            if ind:
                print(f"         {side} indicators: {ind}")
            lv = fmt_levels(d)
            if lv:
                print(f"         {side} level memory: {lv}")



# ==============================================================================
# LIVE TRADER   (inlined from trader.py)
# ==============================================================================
# LU-POI TRADER - live MT5 trading bot (v7).
#
#     python trader.py [--symbol XAUUSD.t] [--risk 1.0] [--min-quality 0.5] [--timeframes M5,M10,M15,M30,H1]
#                      [--dry-run] [--once] [--state trader_state.json] [--log trader.log]
#
# NO login option: the bot attaches to the MetaTrader 5 terminal that is already open and logged
# in on this Windows PC (``mt5.initialize()`` without credentials).  Keep the terminal running.
#
# What it does every minute (after the M1 bar closes):
#   1. pulls the M1 history from the terminal, rebuilds M5/M10/M15/M30/H1 and runs the v6 POI scanner
#      (quality model) exactly like `bot.py scan` -> two POIs per timeframe (above / below);
#   2. for every newly shown POI: BUY LIMIT at the top of a bullish zone / SELL LIMIT at the bottom of a
#      bearish zone, SL at the far edge of the zone, position sized to ``risk_pct`` % of equity.
#      Hedging account -> two half-size legs: leg A TP = +0.4R, leg B TP = +1.5R (server-side).
#      Netting account -> one order with TP = +1.5R; the bot closes half at market when +0.4R is touched;
#   3. POIs no longer shown -> their pending orders are cancelled (mirror policy);
#   4. management: when leg A has been closed (TP1) the SL of leg B is moved to break-even;
#   5. all state (plans, tickets) is persisted to ``--state`` after every action, and on start-up the bot
#      re-adopts its own orders / positions from the terminal (magic number), so a crash / restart is safe.
#
# Server-side SL/TP protect every position even if this script or the PC dies (only the BE move needs
# the bot).  ``--dry-run`` prints every order it would send without trading.

#!/usr/bin/env python3




#: v8 recommended filter (study_results/TRADER_V8.md): M5 only when the spread+commission is <= 8 % of 1R, quality >= 0.55
#: and the selection is not made 13:00-17:00 New York; the other timeframes at quality >= 0.60.
V8_FILTER = "M5:max_cost_r=0.08;min_quality=0.55;sessions=asia|london|preny|ny|lclose/M10|M15|M30|H1:min_quality=0.60"

MAGIC_BASE = 770_000


def setup_logging(path: Optional[str]) -> logging.Logger:
    log = logging.getLogger("trader")
    log.setLevel(logging.INFO)
    fmt = logging.Formatter("%(asctime)s %(levelname)s %(message)s", "%Y-%m-%d %H:%M:%S")
    h = logging.StreamHandler(sys.stdout)
    h.setFormatter(fmt)
    log.addHandler(h)
    if path:
        fh = logging.FileHandler(path, encoding="utf-8")
        fh.setFormatter(fmt)
        log.addHandler(fh)
    return log


# ----------------------------------------------------------------------------- state
class State:
    """Crash-safe JSON state: plans keyed by "TF#poi_id" with their broker tickets."""

    def __init__(self, path: str):
        self.path = Path(path)
        self.plans: Dict[str, dict] = {}
        self.traded: set = set()
        # v10 account protection (persisted so a restart cannot reset the limits)
        self.risk: Dict[str, object] = {"start_balance": None, "day": None, "day_start_equity": None,
                                        "daily_halt_day": None, "halted": False, "halt_time": None, "daily_halts": []}
        # v14: closed EDGE plans in close order [tf, net $, r_net, mart_step] - the martingale state is rebuilt from this list
        self.closed: List[list] = []
        self.load()

    def load(self) -> None:
        if self.path.exists():
            try:
                d = json.loads(self.path.read_text())
                self.plans = d.get("plans", {})
                self.traded = set(d.get("traded", []))
                self.risk.update(d.get("risk", {}))
                self.closed = [list(x) for x in d.get("closed", [])]
            except Exception as e:  # noqa: BLE001
                print(f"state file unreadable ({e}) - starting fresh")

    def save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps({"plans": self.plans, "traded": sorted(self.traded), "risk": self.risk,
                                   "closed": self.closed[-500:],
                                   "saved": time.strftime("%Y-%m-%d %H:%M:%S")}, indent=1, default=str))
        os.replace(tmp, self.path)


# ----------------------------------------------------------------------------- trader
class Trader:
    def __init__(self, broker, cfg: StrategyConfig, tcfg: TraderConfig, state: State, log: logging.Logger,
                 dry_run: bool = False, history_bars: int = 60_000, rebuild_every_min: int = 5,
                 commission_per_lot: float = 0.0):
        self.b = broker
        self.cfg = cfg
        self.t = tcfg
        self.state = state
        self.log = log
        self.dry = dry_run
        self.history_bars = history_bars
        self.rebuild_every = rebuild_every_min
        self.spec: SymbolSpec = broker.spec(commission_per_lot)
        self.magic = MAGIC_BASE + (abs(hash(self.spec.symbol)) % 1000)
        self.hedging = getattr(broker, "hedging", True)
        self.mode = "split" if self.hedging else "netting"
        self.t.exec_mode = self.mode
        self.m1: Optional[pd.DataFrame] = None
        self.last_result: Dict[str, dict] = {}
        self.last_rebuild_bar: Optional[pd.Timestamp] = None
        # v8: per-timeframe trade filter (same rules / same code as the backtest)
        self.filter = TradeFilter.parse(self.t.trade_filter, commission_oz=self.spec.commission_per_lot / self.spec.contract_size,
                                        server_minus_ny_hours=cfg.server_minus_ny_hours if cfg.server_minus_ny_hours is not None else 7.0)
        self.log.info(f"trade filter: {self.filter.describe()}")
        # v12: alternative filter for confluence plans (zone active on another timeframe) - same code as the simulator
        self.conf_filter: Optional[TradeFilter] = TradeFilter.parse(
            self.t.confluence_filter, commission_oz=self.spec.commission_per_lot / self.spec.contract_size,
            server_minus_ny_hours=cfg.server_minus_ny_hours if cfg.server_minus_ny_hours is not None else 7.0) \
            if self.t.confluence_filter else None
        if self.conf_filter is not None:
            self.log.info(f"confluence filter: {self.conf_filter.describe()}")
        if self.t.keep_replaced_bars > 0:
            self.log.info(f"keep replaced orders: {self.t.keep_replaced_bars} bars of their timeframe "
                          f"({'|'.join(self.t.keep_replaced_tfs) or 'all TFs'})")
        if self.t.regime_metric:
            self.log.info(f"v13 regime: {self.t.regime_metric}({self.t.regime_short}/{self.t.regime_long}) < {self.t.regime_threshold} "
                          f"-> range management: ladder {'|'.join(self.t.range_tp_levels) or 'same'} fracs "
                          f"{'|'.join(self.t.range_tp_fracs) or 'equal'} sl_after_leg {'|'.join(self.t.range_sl_after_leg) or 'same'} "
                          f"risk x{self.t.range_risk_scale} ({'|'.join(self.t.range_tfs) or 'all TFs'})")
        self.regime_value: float = float("nan")
        self.regime: str = ""
        # v14: martingale state rebuilt from the persisted closed-plan list (same code as the simulator)
        self.mart = Martingale.replay(self.t, self.state.closed)
        if self.t.mart_mode:
            self.log.info(f"v14 martingale: mode {self.t.mart_mode} mult {self.t.mart_mult} steps <= {self.t.mart_max_steps} "
                          f"risk <= {self.t.mart_max_risk_pct} % scope {self.t.mart_scope} gates tfs {'|'.join(self.t.mart_tfs) or 'all'} "
                          f"sides {'|'.join(self.t.mart_sides) or 'all'} q>={self.t.mart_min_quality} regime {self.t.mart_regime or 'any'} "
                          f"ungated x{self.t.mart_ungated_scale} | state {self.mart.snapshot()} ({len(self.state.closed)} closed plans)")
        if self.t.grid_add_r > 0:
            self.log.info(f"v14 zone grid: deep leg at {self.t.grid_add_r} R into the zone, budget edge {self.t.grid_base_frac} / deep "
                          f"{self.t.grid_add_frac}, ladder {self.t.grid_deep_ladder}, cancel on partial {self.t.grid_cancel_on_partial} "
                          f"({'|'.join(self.t.grid_tfs) or 'all TFs'}, regime {self.t.grid_regime or 'any'})")
        self.log.info(f"symbol {self.spec.symbol} digits {self.spec.digits} contract {self.spec.contract_size} "
                      f"vol {self.spec.volume_min}-{self.spec.volume_max} step {self.spec.volume_step} | account "
                      f"{'HEDGING' if self.hedging else 'NETTING'} -> exec_mode {self.mode} | magic {self.magic} | "
                      f"{'DRY RUN' if dry_run else 'LIVE'}")

    # ------------------------------------------------------------------ data
    def refresh_history(self) -> None:
        if self.m1 is None:
            self.m1 = self.b.m1_history(self.history_bars)
            self.log.info(f"history {len(self.m1)} M1 bars {self.m1.index[0]} -> {self.m1.index[-1]}")
        else:
            fresh = self.b.m1_since(self.m1.index[-1] - pd.Timedelta(days=2))
            if len(fresh):
                self.m1 = pd.concat([self.m1[self.m1.index < fresh.index[0]], fresh])
                self.m1 = self.m1.iloc[-self.history_bars:]

    def current_regime(self) -> str:
        """v13: 'range' | 'trend' from the CLOSED server days of the M1 history ('' when the lever is off).
        Same code as the simulator (lubot/regime.py); the unfinished current day is excluded."""
        if not self.t.regime_metric or self.m1 is None:
            return ""
        d = daily_bars(self.m1)
        v = latest_metric(d, self.t.regime_metric, self.t.regime_short, self.t.regime_long)
        r = regime_of(v, self.t.regime_threshold)
        if r != self.regime:
            self.log.info(f"regime -> {r} ({self.t.regime_metric} = {v:.3f}, threshold {self.t.regime_threshold})")
        self.regime_value, self.regime = v, r
        return r

    def scan(self) -> Dict[str, dict]:
        """Run the scanner on the closed bars.  The last M1 bar returned by MT5 is the FORMING one -> drop it."""
        m1 = self.m1
        # the last bar is still forming if its open minute == current server minute
        tick = self.b.price()
        now_server = pd.Timestamp(tick["time"], unit="s")
        closed = m1[m1.index + pd.Timedelta(minutes=1) <= now_server.floor("min")]
        ohlc = closed[["open", "high", "low", "close", "volume"]]
        scanner = MultiTimeframeScanner(ohlc, self.cfg)
        res = scanner.scan(price=(tick["bid"] + tick["ask"]) / 2.0)
        return res

    # ------------------------------------------------------------------ sync with terminal
    def adopt(self) -> None:
        """Re-attach state to the broker's orders / positions (after restart)."""
        orders = {o.ticket: o for o in self.b.orders(self.magic)}
        poss = {p.ticket: p for p in self.b.positions(self.magic)}
        for key, pl in list(self.state.plans.items()):
            pl["order_tickets"] = [t for t in pl.get("order_tickets", []) if t in orders]
            pl["position_tickets"] = [t for t in pl.get("position_tickets", []) if t in poss]
            # orders that got filled turn into positions with the same comment
            for tk, p in poss.items():
                if p.comment == pl["comment"] and tk not in pl["position_tickets"]:
                    pl["position_tickets"].append(tk)
            if not pl["order_tickets"] and not pl["position_tickets"]:
                self.log.info(f"plan {key} finished (no orders/positions left)")
                self.state.plans.pop(key)
        # orphans with our magic but unknown to the state (state file lost): adopt by comment
        known = {t for pl in self.state.plans.values() for t in pl.get("order_tickets", []) + pl.get("position_tickets", [])}
        for tk, o in orders.items():
            if tk not in known:
                self.log.warning(f"orphan pending order #{tk} {o.comment} -> cancelling")
                self._cancel(tk)
        for tk, p in poss.items():
            if tk not in known:
                self.log.warning(f"orphan position #{tk} {p.comment} - adopting with its current SL/TP")
                self.state.plans[f"orphan#{tk}"] = {"comment": p.comment, "side": p.side, "entry": p.price_open,
                                                     "sl": p.sl, "tp1": None, "tp2": p.tp, "be_price": p.price_open,
                                                     "risk": abs(p.price_open - p.sl) if p.sl else 0.0,
                                                     "order_tickets": [], "position_tickets": [tk], "partial_done": True,
                                                     "tf": "", "poi_id": -1, "key": f"orphan#{tk}"}
        self.state.save()

    # ------------------------------------------------------------------ order actions
    def _cancel(self, ticket: int) -> bool:
        if self.dry:
            self.log.info(f"[dry] cancel order #{ticket}")
            return True
        return self.b.cancel_order(ticket)

    def _place(self, plan: TradePlan, volume: float, tp: float, tag: str) -> Optional[int]:
        if self.dry:
            self.log.info(f"[dry] {plan.side.upper()} LIMIT {volume} @ {plan.entry} sl {plan.sl} tp {tp}  {plan.comment}{tag}")
            return -int(time.time() * 1000) % 10 ** 9
        return self.b.place_limit(plan.side, volume, plan.entry, plan.sl, tp, self.magic, plan.comment + tag)

    def _modify(self, ticket: int, sl: float, tp: float) -> bool:
        if self.dry:
            self.log.info(f"[dry] modify #{ticket} sl {sl} tp {tp}")
            return True
        return self.b.modify_position(ticket, sl, tp)

    def _close_partial(self, pos, volume: float) -> bool:
        if self.dry:
            self.log.info(f"[dry] close {volume} of #{pos.ticket}")
            return True
        return self.b.close_position(pos, volume, "LU partial")

    # ------------------------------------------------------------------ decision
    def _accept(self, plan: TradePlan) -> Optional[str]:
        t = self.t
        if plan.key in self.state.plans:
            return "active"
        if self.state.risk.get("halted"):
            return "HALTED (total loss limit)"
        if self.state.risk.get("daily_halt_day") is not None:
            return "daily loss limit reached - no new trades today"
        if t.one_trade_per_poi and plan.key in self.state.traded:
            return "already traded"
        if t.grades and plan.grade not in t.grades:
            return "grade"
        if t.min_quality is not None and not (plan.quality >= t.min_quality):
            return "quality"
        if t.sides and plan.side not in t.sides:
            return "side"
        n_pos = len({k for k, pl in self.state.plans.items() if pl.get("position_tickets") and not pl.get("grid_leg")})
        n_pend = len({k for k, pl in self.state.plans.items() if pl.get("order_tickets") and not pl.get("position_tickets")
                      and not pl.get("grid_leg")})
        if n_pend >= t.max_pending_orders:
            return "max pending"
        for pl in self.state.plans.values():
            if pl.get("grid_leg"):
                continue                                     # v14: the deep leg belongs to its edge plan
            if pl.get("side") == plan.side and pl.get("zone_top") is not None:
                # v11 dedupe_cross_tf=false: a level shown on another timeframe (confluence) may be traded as well
                if not t.dedupe_cross_tf and pl.get("tf") and pl.get("tf") != plan.tf:
                    continue
                other = TradePlan(side=pl["side"], entry=pl["entry"], sl=pl["sl"], tp1=pl["tp1"] or pl["entry"], tp2=pl["tp2"],
                                  be_price=pl["be_price"], risk=pl["risk"], zone_top=pl["zone_top"], zone_bottom=pl["zone_bottom"])
                if plan.overlaps(other) >= t.dedupe_overlap:
                    return "overlaps active plan"
        px = self.b.price()
        if (plan.is_buy and px["ask"] <= plan.entry) or (not plan.is_buy and px["bid"] >= plan.entry):
            return "price already at/through entry"
        # broker minimum stop distance
        min_dist = self.spec.stops_level_points * self.spec.point
        if min_dist and (abs(plan.entry - plan.sl) < min_dist or abs(plan.entry - plan.tp1) < min_dist):
            return "inside broker stops level"
        return None

    def _confluent_other_tf(self, plan: TradePlan) -> bool:
        """v12: the plan's zone overlaps (>= dedupe_overlap) an active plan (order or position, same side) of ANOTHER TF."""
        for pl in self.state.plans.values():
            if pl.get("grid_leg") or pl.get("side") != plan.side or pl.get("zone_top") is None or not pl.get("tf") or pl.get("tf") == plan.tf:
                continue
            other = TradePlan(side=pl["side"], entry=pl["entry"], sl=pl["sl"], tp1=pl["tp1"] or pl["entry"], tp2=pl["tp2"],
                              be_price=pl["be_price"], risk=pl["risk"], zone_top=pl["zone_top"], zone_bottom=pl["zone_bottom"])
            if plan.overlaps(other) >= self.t.dedupe_overlap:
                return True
        return False

    def on_selection(self, result: Dict[str, dict]) -> None:
        shown_keys = set()
        slot_shown: Dict[Tuple[str, str], str] = {}          # (tf, side) -> key shown now (v12 keep_replaced)
        regime = self.current_regime()                        # v13
        for tf, r in result.items():
            for side in ("above", "below"):
                d = r.get(side)
                if not d:
                    continue
                d = dict(d)
                d["tf"] = tf
                key = f"{tf}#{d['id']}"
                shown_keys.add(key)
                slot_shown[(tf, BUY if side == "below" else SELL)] = key
                plan = TradePlan.from_poi(d, self.t, self.spec, selected_time=r.get("time", ""), regime=regime)
                if plan is None:
                    continue
                if plan.regime == "range" and self.t.range_risk_scale <= 0:
                    self.log.debug(f"skip {key}: range regime (no trading)")
                    continue
                why = self._accept(plan)
                if why == "active":
                    # v12: a kept (replaced) order that is shown again is kept for good
                    pl = self.state.plans.get(key)
                    if pl is not None and pl.get("keep_until"):
                        pl.pop("keep_until", None)
                        self.state.save()
                        self.log.info(f"{key} shown again -> kept order is live again")
                    continue
                if why:
                    self.log.debug(f"skip {key}: {why}")
                    continue
                # v8 trade filter with the live spread (ask - bid) at decision time
                # (v12: a confluence plan - same level active on another TF - is judged by the confluence filter instead)
                px = self.b.price()
                flt = self.filter
                if self.conf_filter is not None and self._confluent_other_tf(plan):
                    flt = self.conf_filter
                    plan.confluent = True
                why = flt.check(d, tf, spread=px["ask"] - px["bid"], when=r.get("time") or None)
                if why:
                    self.log.info(f"filter {key}: {why}")
                    continue
                self.open_plan(plan)
        # mirror policy: cancel pending orders of POIs no longer shown (positions are never touched)
        if self.t.order_policy == "mirror":
            now = time.time()
            for key, pl in list(self.state.plans.items()):
                if key.startswith("orphan"):
                    continue
                if pl.get("grid_leg"):
                    # v14: the deep order follows its edge plan - cancelled when the edge order is cancelled (below) or the edge closes
                    if pl["grid_parent"] not in self.state.plans and pl.get("order_tickets") and not pl.get("position_tickets"):
                        self._cancel_deep(pl["grid_parent"], "edge plan gone")
                    continue
                if key not in shown_keys and pl.get("order_tickets") and not pl.get("position_tickets"):
                    # v12 keep_replaced_bars: the POI was REPLACED by another one on its slot (the slot is still shown) ->
                    # keep the order for N bars of its TF; a cleared slot ('no longer shown') cancels at once
                    slot_key = slot_shown.get((pl.get("tf", ""), pl.get("side", "")))
                    replaced = slot_key is not None and slot_key != key
                    keep_tf = not self.t.keep_replaced_tfs or pl.get("tf") in self.t.keep_replaced_tfs
                    if replaced and self.t.keep_replaced_bars > 0 and keep_tf:
                        if not pl.get("keep_until"):
                            pl["keep_until"] = now + self.t.keep_replaced_bars * TIMEFRAME_MINUTES.get(pl.get("tf", ""), 5) * 60
                            self.state.save()
                            self.log.info(f"{key} replaced on its slot -> order kept for {self.t.keep_replaced_bars} bars")
                            continue
                        if now < pl["keep_until"]:
                            continue
                        reason = "replaced (keep window over)"
                    else:
                        reason = "no longer shown"
                    self.log.info(f"{key} {reason} -> cancel pending {pl['order_tickets']}")
                    for tk in pl["order_tickets"]:
                        self._cancel(tk)
                    pl["order_tickets"] = []
                    self.state.plans.pop(key)
                    self._cancel_deep(key, reason)
                    self.state.save()

    def open_plan(self, plan: TradePlan) -> None:
        equity = self.b.equity if self.t.size_on == "equity" else self.b.balance
        # v14: sequence sizing (streak from the closed-plan list) + the edge leg's share of the budget when a deep leg follows
        if self.mart.on and not plan.grid_leg:
            m, step = self.mart.scale(plan, equity)
            plan.mart_scale, plan.mart_step = m, step
            apply_mart_ladder(plan, self.t, self.spec)
            if step:
                self.log.info(f"{plan.key}: martingale step {step} -> risk x{m:.3f} (state {self.mart.snapshot()})")
        deep_after = grid_wanted(plan, self.t)
        if deep_after:
            plan.risk_scale = (plan.risk_scale if plan.risk_scale > 0 else 1.0) * self.t.grid_base_frac
        if not self._open_plan_orders(plan, equity):
            return
        if deep_after:
            deep = grid_deep_plan(plan, self.t, self.spec)
            if deep is not None:
                deep.mart_scale, deep.mart_step = plan.mart_scale, plan.mart_step
                self._open_plan_orders(deep, equity)

    def _open_plan_orders(self, plan: TradePlan, equity: float) -> bool:
        sz = size_plan(plan, equity, self.t, self.spec)
        if not sz.ok:
            self.log.info(f"skip {plan.key}: {sz.reason}")
            return False
        need = self.spec.margin_required(sz.lots_total, plan.entry)
        free = float(getattr(self.b.refresh_account(), "margin_free", equity))
        if need > free * self.t.margin_buffer:
            self.log.info(f"skip {plan.key}: margin {need:.0f} > free {free:.0f} x {self.t.margin_buffer}")
            return False
        tickets = []
        ladder_legs: List[dict] = []
        if self.mode == "split" and len(plan.tps) > 2 and sz.lots_legs:
            # v10 multi-TP ladder: one limit leg per target (server-side TP), all with the zone SL.  Legs merged away by
            # ladder_fallback=merge have volume 0 and are not sent.
            for i, (vol, tp) in enumerate(zip(sz.lots_legs, plan.tps)):
                if vol <= 0:
                    continue
                tk = self._place(plan, vol, tp, f" L{i + 1}")
                if tk is None:
                    self.log.error(f"{plan.key}: ladder leg {i + 1} rejected -> cancelling the legs already placed")
                    for tk2 in tickets:
                        self._cancel(tk2)
                    return False
                tickets.append(tk)
                ladder_legs.append({"idx": i, "ticket": tk, "tp": tp, "vol": vol, "closed": False})
        elif self.mode == "split":
            t1 = self._place(plan, sz.lots_leg1, plan.tp1, " A")
            t2 = self._place(plan, sz.lots_leg2, plan.tp2, " B")
            tickets = [t for t in (t1, t2) if t is not None]
            if len(tickets) == 1:      # one leg rejected -> do not leave a half plan
                self.log.error(f"{plan.key}: only one leg accepted -> cancelling it")
                self._cancel(tickets[0])
                return False
        else:
            t1 = self._place(plan, sz.lots_total, plan.tp2, "")
            tickets = [t1] if t1 is not None else []
        if not tickets:
            self.log.error(f"{plan.key}: order placement failed")
            return False
        rec = plan.to_dict()
        rec.update(key=plan.key, comment=plan.comment, order_tickets=tickets, position_tickets=[], partial_done=False,
                   leg_a_ticket=tickets[0] if (self.mode == "split" and not ladder_legs) else None,
                   leg_b_ticket=(tickets[1] if self.mode == "split" else tickets[0]) if not ladder_legs else None,
                   ladder=ladder_legs, n_closed=0,
                   lots_total=sz.lots_total, lots_leg1=sz.lots_leg1, lots_leg2=sz.lots_leg2, risk_money=sz.risk_money,
                   placed=time.strftime("%Y-%m-%d %H:%M:%S"))
        self.state.plans[plan.key] = rec
        self.state.traded.add(plan.key)
        self.state.save()
        self.log.info(f"NEW {plan.side.upper()} LIMIT {plan.tf} {plan.kind} #{plan.poi_id}{' DEEP' if plan.grid_leg else ''} "
                      f"{sz.lots_total} lots @ {plan.entry} {('[' + plan.regime + '] ') if plan.regime else ''}"
                      f"{('[mart ' + str(plan.mart_step) + ' x' + format(plan.mart_scale, '.2f') + '] ') if plan.mart_step else ''}"
                      f"sl {plan.sl} tp1 {plan.tp1} tp2 {plan.tp2} (1R={plan.risk:.2f}, risk ${sz.risk_money:.0f}, "
                      f"P={plan.quality:.2f} {plan.grade}) tickets {tickets}")
        return True

    # ------------------------------------------------------------------ management
    # ------------------------------------------------------------------ v10 account protection
    def _server_day(self) -> str:
        """Server date (YYYY-MM-DD) of the current tick - the broker's trading day."""
        tk = self.b.tick() if hasattr(self.b, "tick") else None
        ts = getattr(tk, "time", None)
        return time.strftime("%Y-%m-%d", time.gmtime(ts)) if ts else time.strftime("%Y-%m-%d", time.gmtime())

    def _flatten(self, reason: str) -> None:
        """Cancel every pending order and close every position of this bot (all plans)."""
        for o in self.b.orders(self.magic):
            self._cancel(o.ticket)
        for p in self.b.positions(self.magic):
            if self.dry:
                self.log.info(f"[dry] close #{p.ticket} ({reason})")
            else:
                self.b.close_position(p, None, f"LU {reason}")
        for key, pl in list(self.state.plans.items()):
            pl["order_tickets"] = []
            pl["position_tickets"] = []
            self.state.plans.pop(key)

    def check_risk_limits(self) -> bool:
        """Daily / total loss limits (TraderConfig.max_daily_loss_pct / max_total_loss_pct, 0 = off).
        Equity = balance + floating P/L from the terminal.  Returns True when trading is allowed this loop."""
        t, rk = self.t, self.state.risk
        if not (t.max_daily_loss_pct > 0 or t.max_total_loss_pct > 0):
            return True
        acc = self.b.refresh_account()
        equity, balance = float(acc.equity), float(acc.balance)
        changed = False
        if rk.get("start_balance") is None:
            rk["start_balance"] = balance
            changed = True
        day = self._server_day()
        if rk.get("day") != day:
            rk["day"] = day
            rk["day_start_equity"] = equity
            if rk.get("daily_halt_day") is not None:
                self.log.info(f"new server day {day}: daily loss limit reset")
            rk["daily_halt_day"] = None
            changed = True
        if rk.get("halted"):
            if changed:
                self.state.save()
            return False
        if t.max_total_loss_pct > 0 and equity <= float(rk["start_balance"]) * (1.0 - t.max_total_loss_pct / 100.0):
            self.log.error(f"TOTAL LOSS LIMIT: equity {equity:.2f} <= {100 - t.max_total_loss_pct:.1f} % of start balance "
                           f"{float(rk['start_balance']):.2f} -> closing everything and HALTING the bot for good")
            self._flatten("total loss limit")
            rk["halted"] = True
            rk["halt_time"] = time.strftime("%Y-%m-%d %H:%M:%S")
            self.state.save()
            return False
        if t.max_daily_loss_pct > 0 and rk.get("daily_halt_day") is None and \
                equity <= float(rk["day_start_equity"]) * (1.0 - t.max_daily_loss_pct / 100.0):
            self.log.error(f"DAILY LOSS LIMIT: equity {equity:.2f} <= {100 - t.max_daily_loss_pct:.1f} % of day-start equity "
                           f"{float(rk['day_start_equity']):.2f} -> closing everything, no new trades until the next server day")
            self._flatten("daily loss limit")
            rk["daily_halt_day"] = day
            rk["daily_halts"] = list(rk.get("daily_halts", [])) + [time.strftime("%Y-%m-%d %H:%M:%S")]
            self.state.save()
            return False
        if changed:
            self.state.save()
        return rk.get("daily_halt_day") is None

    def manage(self) -> None:
        """Runs every loop: detect fills, move to break-even after TP1, netting partial close, clean up."""
        orders = {o.ticket: o for o in self.b.orders(self.magic)}
        poss = {p.ticket: p for p in self.b.positions(self.magic)}
        by_comment: Dict[str, List] = {}
        for p in poss.values():
            by_comment.setdefault(p.comment, []).append(p)
        changed = False
        for key, pl in list(self.state.plans.items()):
            # 1) orders -> positions (fills).  MT5: the position ticket == the ticket of the pending order
            #    that opened it; fall back to matching the order comment.
            still = [t for t in pl["order_tickets"] if t in orders]
            for t in pl["order_tickets"]:
                if t in orders:
                    continue
                if t in poss and t not in pl["position_tickets"]:
                    pl["position_tickets"].append(t)
                    pl.setdefault("all_position_tickets", []).append(t)      # v14: kept for the realised P&L lookup
                    self.log.info(f"{key}: order #{t} FILLED @ {poss[t].price_open}")
                    changed = True
                elif t not in poss:
                    tag = " A" if t == pl.get("leg_a_ticket") else " B" if t == pl.get("leg_b_ticket") else ""
                    for p in by_comment.get(pl["comment"] + tag, []):
                        if p.ticket not in pl["position_tickets"]:
                            pl["position_tickets"].append(p.ticket)
                            pl.setdefault("all_position_tickets", []).append(p.ticket)
                            self.log.info(f"{key}: order #{t} FILLED -> position #{p.ticket} @ {p.price_open}")
                            changed = True
            pl["order_tickets"] = still
            open_pos = [poss[t] for t in pl["position_tickets"] if t in poss]
            pl["position_tickets"] = [p.ticket for p in open_pos]
            # 2a) v10 ladder (3+ legs): stop schedule for the remaining legs after every closed target leg
            if pl.get("ladder") and open_pos:
                if self._manage_ladder(key, pl, orders, poss, open_pos):
                    changed = True
            # 2) break-even after TP1
            elif open_pos and not pl.get("partial_done"):
                if self.mode == "split":
                    leg_a = pl.get("leg_a_ticket")
                    leg_a_alive = leg_a in orders or leg_a in poss
                    leg_a_pos = poss.get(leg_a)
                    if leg_a_pos is not None:
                        pl["leg_a_seen"] = True
                    if leg_a is not None and not leg_a_alive and (pl.get("leg_a_seen") or leg_a not in pl["order_tickets"]):
                        # leg A is gone while leg B is still open -> leg A closed by its TP1 (a stop would have
                        # taken both legs at the same price) -> move leg B to break-even
                        for p in open_pos:
                            if abs(p.sl - pl["be_price"]) > self.spec.point / 2:
                                ok = self._modify(p.ticket, pl["be_price"], p.tp)
                                self.log.info(f"{key}: leg A closed (TP1) -> leg B #{p.ticket} SL -> BE {pl['be_price']} ({'ok' if ok else 'FAILED'})")
                                if not ok:
                                    continue
                        pl["partial_done"] = True
                        changed = True
                else:
                    px = self.b.price()
                    ref = px["bid"] if pl["side"] == BUY else px["ask"]
                    touched = (ref >= pl["tp1"]) if pl["side"] == BUY else (ref <= pl["tp1"])
                    if touched:
                        for p in open_pos:
                            part = self.spec.round_volume_down(p.volume * self.t.partial_frac)
                            if part >= self.spec.volume_min and p.volume - part >= self.spec.volume_min - 1e-9:
                                ok = self._close_partial(p, part)
                                self.log.info(f"{key}: TP1 touched -> closed {part} of #{p.ticket} ({'ok' if ok else 'FAILED'})")
                            ok2 = self._modify(p.ticket, pl["be_price"], p.tp)
                            self.log.info(f"{key}: SL -> BE {pl['be_price']} ({'ok' if ok2 else 'FAILED'})")
                        pl["partial_done"] = True
                        changed = True
            # 2b) v14 grid: the deep order is withdrawn once the edge leg has taken its first partial
            if pl.get("partial_done") and not pl.get("grid_leg") and self.t.grid_add_r > 0 and self.t.grid_cancel_on_partial:
                if self._cancel_deep(key, "edge took a partial"):
                    changed = True
            # 3) finished?
            if not pl["order_tickets"] and not pl["position_tickets"]:
                self.log.info(f"{key}: all legs closed -> plan finished")
                if pl.get("grid_leg"):
                    pass                                     # the deep leg's outcome is part of the edge plan's (not counted twice)
                else:
                    self._record_closed(key, pl)
                    self._cancel_deep(key, "edge closed")
                self.state.plans.pop(key)
                changed = True
        if changed:
            self.state.save()

    # ------------------------------------------------------------------ v14 martingale / grid bookkeeping
    def _record_closed(self, key: str, pl: dict) -> None:
        """An EDGE plan finished: realised net $ from the broker's deal history (all its position tickets) -> closed list ->
        martingale state (same rule as the simulator: r_net = net / risk_money; BE exits are neutral)."""
        if not self.mart.on:
            return
        tickets = pl.get("all_position_tickets") or []
        net = 0.0
        known = False
        for tk in tickets:
            v = self.b.position_pnl(tk) if hasattr(self.b, "position_pnl") else None
            if v is not None:
                net += v
                known = True
        if not known:
            self.log.warning(f"{key}: no deal history for tickets {tickets} -> treated as break-even for the martingale")
            net = 0.0
        rm = float(pl.get("risk_money") or 0.0)
        r_net = net / rm if rm > 0 else 0.0
        step = int(pl.get("mart_step") or 0)
        self.state.closed.append([pl.get("tf", ""), round(net, 2), round(r_net, 4), step])
        self.mart.on_close(pl.get("tf", ""), net, r_net, step)
        self.log.info(f"{key}: closed net {net:+.2f} $ ({r_net:+.2f} R, step {step}) -> martingale state {self.mart.snapshot()}")

    def _cancel_deep(self, edge_key: str, reason: str) -> bool:
        """Cancel the pending deep order of ``edge_key`` (a deep leg that is already a position is left alone)."""
        dk = edge_key + "+g"
        pl = self.state.plans.get(dk)
        if pl is None or pl.get("position_tickets") or not pl.get("order_tickets"):
            return False
        self.log.info(f"{dk}: {reason} -> cancel deep order {pl['order_tickets']}")
        for tk in pl["order_tickets"]:
            self._cancel(tk)
        pl["order_tickets"] = []
        self.state.plans.pop(dk, None)
        return True

    def _manage_ladder(self, key: str, pl: dict, orders: dict, poss: dict, open_pos: list) -> bool:
        """v10 N-leg ladder: a leg whose ticket is neither a pending order nor an open position while OTHER legs are still
        open was closed by its server-side TP (a stop takes every leg at once).  For every newly closed target leg apply
        the stop schedule to the remaining legs: ``sl_after_leg`` (per-leg R offsets, 'x' = leave, 0 = BE) if set, else
        classic BE after the first closed leg (``be_on_partial``) and ``ratchet_sl`` (stop -> previous target).
        Same rules as ``lubot/portfolio_sim.py``.  Returns True when the state changed."""
        t = self.t
        changed = False
        buy = pl["side"] == BUY
        sgn = 1.0 if buy else -1.0
        for leg in pl["ladder"]:
            if leg["closed"]:
                continue
            tk = leg["ticket"]
            if tk in orders:
                continue
            if tk in poss:
                leg["seen"] = True
                continue
            if not leg.get("seen") and tk in pl.get("order_tickets", []):
                continue
            # gone while other legs are open -> closed by its TP
            leg["closed"] = True
            pl["n_closed"] = int(pl.get("n_closed", 0)) + 1
            k = leg["idx"]
            new_sl = None
            sl_after_leg = tuple(pl.get("sl_after_leg") or ()) or t.sl_after_leg     # v13: range plans carry their own schedule
            if sl_after_leg:
                spec_k = sl_after_leg[k] if k < len(sl_after_leg) else "x"
                if str(spec_k).lower() not in ("x", "", "none"):
                    new_sl = pl["be_price"] if abs(float(spec_k)) < 1e-12 else \
                        self.spec.round_price(pl["entry"] + sgn * float(spec_k) * pl["risk"])
            else:
                if pl["n_closed"] == 1 and t.be_on_partial:
                    new_sl = pl["be_price"]
                if t.ratchet_sl and pl["n_closed"] >= 2:
                    closed_tps = sorted((l["tp"] for l in pl["ladder"] if l["closed"] and l["tp"] > 0), reverse=not buy)
                    if len(closed_tps) >= 2:
                        new_sl = closed_tps[-2]
            pl["partial_done"] = True
            changed = True
            self.log.info(f"{key}: ladder leg {k + 1} closed at TP {leg['tp']} ({pl['n_closed']} of {len(pl['ladder'])})")
            if new_sl is None:
                continue
            for p in open_pos:
                better = new_sl > p.sl if buy else new_sl < p.sl
                if p.sl == 0 or better:
                    ok = self._modify(p.ticket, new_sl, p.tp)
                    self.log.info(f"{key}: leg #{p.ticket} SL {p.sl} -> {new_sl} ({'ok' if ok else 'FAILED'})")
                    if ok:
                        p.sl = new_sl
        return changed

    # ------------------------------------------------------------------ loop
    def step(self) -> None:
        if not self.check_risk_limits():
            if self.state.risk.get("halted"):
                return                                   # bot is finished; nothing else to do
        self.refresh_history()
        self.manage()
        if not self.check_risk_limits():                 # re-check with the fills detected by manage()
            return
        res = self.scan()
        self.last_result = res
        self.on_selection(res)
        self.manage()
        self.check_risk_limits()

    def status_line(self) -> str:
        px = self.b.price()
        n_pos = sum(1 for pl in self.state.plans.values() if pl.get("position_tickets"))
        n_pend = sum(1 for pl in self.state.plans.values() if pl.get("order_tickets") and not pl.get("position_tickets"))
        acc = self.b.refresh_account()
        rk = self.state.risk
        flag = " | HALTED" if rk.get("halted") else (" | daily limit hit - flat until next day" if rk.get("daily_halt_day") else "")
        rg = f" | regime {self.regime} ({self.t.regime_metric} {self.regime_value:.3f} < {self.t.regime_threshold})" if self.regime else ""   # v13
        mt = ""
        if self.mart.on:                                                                                                        # v14
            st = self.mart.snapshot()
            mt = " | mart " + " ".join(f"{k}:k{v['k']}" + (f"/def{v['deficit']:.0f}" if v['deficit'] else "") for k, v in st.items()) if st else " | mart k0"
        return (f"bid {px['bid']:.2f} ask {px['ask']:.2f} | equity {acc.equity:.2f} balance {acc.balance:.2f} | "
                f"open plans {n_pos} pending {n_pend}{rg}{mt}{flag}")


# ----------------------------------------------------------------------------- main
def main(argv=None):
    _materialize(["models/quality_model.json"], Path(__file__).resolve().parent)
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--symbol", default="XAUUSD.t")
    ap.add_argument("--path", default=None, help="optional path to terminal64.exe (only if several terminals are installed)")
    ap.add_argument("--risk", type=float, default=1.0, help="%% of equity risked per trade (entry -> SL)")
    ap.add_argument("--min-quality", type=float, default=0.50, help="scanner min P(bounce) (0.60 = ~3 zones/day, higher hit-rate)")
    ap.add_argument("--grades", default="", help="only trade these grades, e.g. A|B ('' = all)")
    ap.add_argument("--timeframes", default="M5,M10,M15,M30,H1")
    ap.add_argument("--trader", default=None, help="TraderConfig overrides key=value,... (partial_r, tp2_r, max_open_positions, ...)")
    ap.add_argument("--max-daily-loss", type=float, default=4.5, help="%% of day-start equity: flatten + no new trades until the next server day (0 = off)")
    ap.add_argument("--max-total-loss", type=float, default=9.0, help="%% of the start balance: flatten + HALT the bot for good (0 = off)")
    ap.add_argument("--trade-filter", default=V8_FILTER,
                    help="v8 per-timeframe trade filter (lubot/trade_filter.py); '' = v7 behaviour (no filter). Default = the v8 recommendation")
    ap.add_argument("--confluence-filter", default="",
                    help="v12: filter used INSTEAD of --trade-filter when the zone is already active on another timeframe ('' = off)")
    ap.add_argument("--set", dest="overrides", default=None, help="StrategyConfig overrides key=value,...")
    ap.add_argument("--commission", type=float, default=0.0, help="round-turn commission per lot (for sizing info only)")
    ap.add_argument("--history", type=int, default=60_000)
    ap.add_argument("--state", default="trader_state.json")
    ap.add_argument("--log", default="trader.log")
    ap.add_argument("--dry-run", action="store_true", help="scan + print orders, do not trade")
    ap.add_argument("--once", action="store_true")
    ap.add_argument("--interval", type=int, default=60)
    a = ap.parse_args(argv)

    log = setup_logging(a.log)
    cfg = StrategyConfig(symbol=a.symbol, timeframes=tuple(x.strip() for x in a.timeframes.split(",")), min_quality=a.min_quality)
    if a.overrides:
        cfg = apply_overrides(cfg, a.overrides)
    tcfg = TraderConfig(risk_pct=a.risk, grades=tuple(g for g in a.grades.split("|") if g), trade_filter=a.trade_filter,
                        confluence_filter=a.confluence_filter, max_daily_loss_pct=a.max_daily_loss,
                        max_total_loss_pct=a.max_total_loss).override(a.trader)
    broker = MT5Broker(a.symbol, path=a.path)
    cfg.server_utc_offset_hours = broker.server_utc_offset_hours()
    log.info(f"attached to MT5: account {broker.account.login} ({broker.account.server}) {broker.account.currency} "
             f"balance {broker.account.balance:.2f} | server UTC offset {cfg.server_utc_offset_hours:+.1f}h")
    state = State(a.state)
    tr = Trader(broker, cfg, tcfg, state, log, dry_run=a.dry_run, history_bars=a.history, commission_per_lot=a.commission)
    log.info(f"account protection: daily loss limit {a.max_daily_loss} % | total loss limit {a.max_total_loss} % "
             f"(state: start balance {state.risk.get('start_balance')}, halted {state.risk.get('halted')})")
    if state.risk.get("halted"):
        log.error(f"bot is HALTED since {state.risk.get('halt_time')} (total loss limit). Delete {a.state} to reset - at your own risk.")
    tr.adopt()
    try:
        while True:
            t0 = time.time()
            try:
                tr.step()
                log.info(tr.status_line() + f" | scan {time.time() - t0:.1f}s")
                if a.once:
                    print_scan(tr.last_result)
            except Exception as e:  # noqa: BLE001
                log.exception(f"loop error: {e}")
            if a.once:
                break
            wait_for_next_minute(3.0)
    except KeyboardInterrupt:
        log.info("stopped by user (orders/positions stay in the terminal with their server-side SL/TP)")
    finally:
        broker.shutdown()

# ==============================================================================
# v14-A BACKTEST ENTRY POINT   (the shipped run_trader.bat configuration)
# ==============================================================================
# Reproduces the v14-A study result through the M1 portfolio simulator:
#   python lubot_trader_v14_single.py --backtest --csv data/xauusd_m1.csv
# It reads the recorded selection stream (study_results/sel_v10_<TF>.pkl) and applies
# exactly the TraderConfig shipped in run_trader.bat (v14-A = v13-A + the asymmetric
# martingale sizing: x1.5 up on HTF buys after a loss, x0.5 down elsewhere).

V14A_TFS = ("M5", "M10", "M15", "M30", "H1")
V14A_TRADER = ("tp_levels=0.6|1.2|2.4|4.8,tp_fracs=1|1|1|1,ladder_fallback=merge,dedupe_cross_tf=false,"
               "keep_replaced_bars=1,keep_replaced_tfs=M10|M15|M30|H1,"
               "regime_metric=adr_ratio,regime_threshold=1.0,regime_short=5,regime_long=20,"
               "range_tp_levels=0.5|1.0|1.5|2.5,range_tp_fracs=1|1|1|1,range_sl_after_leg=0|0.3|x|x,"
               "mart_mode=mult,mart_mult=1.5,mart_max_steps=3,mart_max_risk_pct=3,mart_scope=tf,"
               "mart_tfs=M10|M15|M30|H1,mart_sides=buy,mart_ungated_scale=0.5")
V14A_TRADE_FILTER = ("M5:max_cost_r=0.08;min_quality=0.55;sessions=asia|london|preny|ny|lclose/"
                     "M10:min_quality=0.57/M15:min_quality=0.60/M30|H1:min_quality=0.57")
V14A_CONFLUENCE_FILTER = ("M5:max_cost_r=0.08;min_quality=0.55;sessions=asia|london|preny|ny|lclose/"
                          "M10:min_quality=0.50/M15:min_quality=0.60/M30|H1:min_quality=0.57")
V14A_BASE = ("risk_pct=1.0,exec_mode=split,sl_slippage=0.10,market_slippage=0.05,max_open_positions=4,"
             "dedupe_overlap=0.5,ladder_fallback=merge")


def v14a_config(over: str = "", risk: float = 1.0) -> "TraderConfig":
    """v12-A base + v13-A regime lever + v14-A asymmetric martingale (identical to the bat strings)."""
    t = TraderConfig(risk_pct=risk, trade_filter=V14A_TRADE_FILTER, confluence_filter=V14A_CONFLUENCE_FILTER,
                     max_daily_loss_pct=4.5, max_total_loss_pct=9.0)
    return t.override(V14A_BASE).override(V14A_TRADER).override(over)


def load_selections(pattern: str) -> "pd.DataFrame":
    """Load and merge recorded selection pickles matching ``pattern`` (backtest_trader.load_selections)."""
    files = sorted(glob.glob(pattern))
    if not files:
        raise SystemExit(f"no selection files match {pattern}")
    parts = [p for p in (pd.read_pickle(f) for f in files) if len(p)]
    df = pd.concat(parts, ignore_index=True).sort_values("t").reset_index(drop=True)   # default sort: matches the original
    print(f"selections: {len(df)} events from {len(files)} files, TFs {sorted(df.tf.unique())}, "
          f"{df.t.min()} -> {df.t.max()}", flush=True)
    return df


def load_year(csv: str, start: str = "2025-09-01"):
    """M1 bars from ``start`` + the v10 selection stream used by the v13/v14 studies."""
    m1 = load_mt5_csv(csv)[start:]
    sel = _v14a_selections()
    return m1, sel


def spec_override(spec: "SymbolSpec", text: str) -> "SymbolSpec":
    for pair in (text or "").split(","):
        if not pair.strip():
            continue
        k, v = pair.split("=", 1)
        k = k.strip()
        cur = getattr(spec, k)
        setattr(spec, k, type(cur)(v) if not isinstance(cur, str) else v)
    return spec


def main_backtest(argv=None):
    ap = argparse.ArgumentParser(description="v14-A portfolio backtest through the M1 simulator (v13-A + asymmetric martingale)")
    ap.add_argument("--csv", required=True, help="M1 CSV export from MT5")
    ap.add_argument("--sel", default="", help="glob of recorded selection pickles (default: study_results/sel_v10_<TF>.pkl)")
    ap.add_argument("--from", dest="start", default="2025-09-01")
    ap.add_argument("--to", dest="end", default=None)
    ap.add_argument("--risk", type=float, default=1.0)
    ap.add_argument("--trader", default="", help="extra TraderConfig overrides on top of v14-A")
    ap.add_argument("--spec", default="", help="SymbolSpec overrides key=value,...")
    ap.add_argument("--out", default="v14a_backtest")
    a = ap.parse_args(argv)
    m1 = load_mt5_csv(a.csv)[a.start:]
    if a.sel:
        sel = load_selections(a.sel)
    else:
        sel = _v14a_selections()
    print(f"m1 {len(m1)} bars {m1.index[0]} -> {m1.index[-1]} | sel {len(sel)} events", flush=True)
    tcfg = v14a_config(a.trader, a.risk)
    spec = spec_override(SymbolSpec(), a.spec)
    res = PortfolioSimulator(m1, sel, tcfg, spec, start=None, end=a.end).run()
    s = res.summary()
    print("\n===== v14-A BACKTEST =====")
    for k in ("trades", "return_%", "max_dd_%", "profit_factor", "win_%", "range_trades", "end_balance"):
        if k in s:
            print(f"  {k:<16} {s[k]}")
    Path(a.out).parent.mkdir(parents=True, exist_ok=True)
    res.trades.to_csv(f"{a.out}_trades.csv", index=False)
    res.equity.to_csv(f"{a.out}_equity.csv")
    json.dump(s, open(f"{a.out}_summary.json", "w"), indent=1, default=str)
    print(f"-> {a.out}_trades.csv / _equity.csv / _summary.json")
    return s


if __name__ == "__main__":
    if "--backtest" in sys.argv[1:]:
        main_backtest([x for x in sys.argv[1:] if x != "--backtest"])
    else:
        main()
